INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am2_l01',2,1,1,'A Private Conversation','私人谈话','句子成分与语序 · 五种基本句型 · 疑问与否定 · how用法与频率','市中心剧院 · 被身后情侣大声聊天打扰','{"q":"Listen and answer — Why was the writer unhappy at the theater?","options":["The play was boring","A couple behind kept talking","His seat was bad","The actors were too quiet"],"answer_index":1}'::jsonb,'{"title":"句子的骨架(用本课句子看懂它)","intro":"先认识句子的几个\"零件\",再做题就不抽象了。下面全用本课句子举例。","table":{"headers":["句子成分","看本课例子"],"rows":[["主语 = 句子在说\"谁/什么\"","The play was really funny.(主语 = The play)"],["谓语动词 = 主语\"做什么/是什么\"","The play was really funny.(谓语 = was)"],["系动词 = 不表动作,像\"等号\",连接主语和描述(be / look / feel / get)","I got angry.(系动词 = got,\"变得\"生气)"],["表语 = 系动词后面补充说明主语的词","The play was really funny.(表语 = really funny)"],["宾语 = 动作落在谁/什么上","I couldn''t hear the actors.(宾语 = the actors)"],["双宾语 = 给\"人\" + \"物\"","She gave me a great seat.(me + a great seat)"]]},"specialRules":[{"rule":"宾语补足语 = 补充说明宾语;判别法:中间加 be 能成句 → They made him captain(him is captain ✓)","mark":"判别法"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l01',1,NULL,'Last Friday I went to the theater downtown.','上周五我去了市中心的剧院。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l01',2,NULL,'I had a great seat, right in the center.','我的座位很好,正在中间。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l01',3,NULL,'The play was a comedy, and it was really funny.','那出戏是喜剧,非常好笑。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l01',4,NULL,'But I didn''t enjoy it at all.','可我一点也没享受。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l01',5,NULL,'A young couple was sitting behind me, and they were talking loudly the whole time.','一对年轻情侣坐在我后面,全程大声说话。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l01',6,NULL,'I got angry because I couldn''t hear the actors.','我很生气,因为我听不见演员的台词。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l01',7,NULL,'I turned around and looked at them, but they didn''t pay any attention.','我转过身看着他们,可他们毫不理会。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l01',8,NULL,'In the end I couldn''t bear it.','最后我实在忍不了了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l01',9,NULL,'I turned around again. "I can''t hear a word!" I said angrily.','我又转过身。"我一个字都听不见!"我生气地说。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l01',10,NULL,'"It''s none of your business," the young man said rudely.','"不关你的事,"那个年轻男人无礼地说。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l01',11,NULL,'"This is a private conversation!"','"这是私人谈话!"') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
