INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l01',5,'am2_l01_gp1','choice','{"stem":"选出语序正确的句子:","options":["I went yesterday to the theater.","Yesterday I went to the theater.","I yesterday went to the theater.","To the theater I went yesterday."],"answer_index":1,"explanation_cn":"时间词(yesterday)放句首或句尾都可以,但不能插在句子中间。✓ Yesterday I went to the theater. / I went to the theater yesterday. 其他说法都把 yesterday 卡进了句子内部,语序乱了。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l01',5,'am2_l01_gp1','choice','{"stem":"时间状语可放句首或句尾。下列哪句与 \"Every morning she reads the news\" 同义且正确?","options":["She reads the news every morning.","She every morning reads the news.","Reads she the news every morning.","She reads every morning the news."],"answer_index":0,"explanation_cn":"时间状语(every morning)可以整体搬家:句首或句尾都对。✓ She reads the news every morning. 注意只能整体移动,不能拆开塞进句子中间。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l01',5,'am2_l01_gp1','choice','{"stem":"把 the actors / couldn''t / I / hear 组成正确的句子:","options":["Couldn''t I hear the actors.","The actors I couldn''t hear.","I the actors couldn''t hear.","I couldn''t hear the actors."],"answer_index":3,"explanation_cn":"按\"谁 + 做什么 + 对象\"排:I(谁)couldn''t hear(做什么)the actors(对象)。✓ I couldn''t hear the actors."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l01',5,'am2_l01_gp2','choice','{"stem":"\"She can swim well.\" 句中 can 是哪类词?","options":["实义动词","助动词","情态动词","系动词"],"answer_index":2,"explanation_cn":"can(能/会)不表示具体动作,它放在动词前面表示\"有能力做\",这类词叫情态动词,同类的还有 will、must。✓ She can swim well."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l01',5,'am2_l01_gp5','choice','{"stem":"\"She gave me a great seat.\" 换一种说法:She gave a great seat ___ me.","options":["to","for","at","with"],"answer_index":0,"explanation_cn":"give 有两种说法:give + 人 + 物,或 give + 物 + to + 人。\"物\"放前面时,\"人\"前要加 to。✓ She gave a great seat to me. 易错:不用 for(buy 才和 for 搭配)。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l01',5,'am2_l01_gp3','choice','{"stem":"The pizza smells ___.","options":["badly","good","well","nicely"],"answer_index":1,"stem_cn":"这披萨闻起来很香。","explanation_cn":"smell(闻起来)这类词后面接形容词,描述东西本身:✓ The pizza smells good.(比萨闻着香)。good 说\"东西怎么样\",well 说\"动作做得怎么样\",这里说的是比萨,所以用 good。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l01',5,'am2_l01_gp3','choice','{"stem":"He looked ___ when he heard the news.","options":["angry","anger","angrily","angers"],"answer_index":0,"stem_cn":"他听到那消息时看起来很生气。","explanation_cn":"look 在这里是\"看起来\",后面接形容词说明\"他\"的状态:✓ He looked angry.(他看起来很生气)。angrily 是\"生气地做某事\",这句没有动作,所以不用。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l01',5,'am2_l01_gp4','choice','{"stem":"\"The play was really funny.\" 属于哪种句型?","options":["主谓","主谓双宾","主系表","主谓宾"],"answer_index":2,"explanation_cn":"The play(主语,说的是\"什么\")+ was(系动词,像个等号)+ really funny(表语,描述主语)——\"谁/什么 + 是 + 怎么样\"就是主系表。语法卡第一行的例子就是这句。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l01',5,'am2_l01_gp4','choice','{"stem":"下列哪句不完整,动词后面还缺\"什么\"(缺宾语)?","options":["He arrived yesterday.","I really enjoyed.","They were talking loudly.","She smiled."],"answer_index":1,"explanation_cn":"enjoy(喜欢/享受)必须说清\"享受什么\",后面一定要带对象(宾语):✓ I really enjoyed it. 另外三句的动词(arrived 到达、were talking 说话、smiled 微笑)自己就能把意思说完整,不需要对象。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l01',5,'am2_l01_gp4','choice','{"stem":"哪句的 play 后面没有宾语(动作的对象),意思也完整?","options":["She plays the piano.","We played a game.","The kids play in the park.","They play soccer."],"answer_index":2,"explanation_cn":"The kids play in the park 里的 in the park 说的是\"在哪儿玩\"(地点),不是玩的对象,play 后面没有宾语,意思照样完整——这时 play = 玩耍。the piano、a game、soccer 都是 play 的对象。play 两种用法都对,区别就在带不带对象。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l01',5,'am2_l01_gp5','choice','{"stem":"哪句是复合宾语?(判别法:宾语后面加 be 能成句,如 him is captain)","options":["He bought me coffee.","They made him captain.","I told her the truth.","She gave him a ticket."],"answer_index":1,"explanation_cn":"They made him captain:him 和 captain 中间加 be 能说通(him is captain,他是队长),所以 captain 是补充说明 him 的宾语补足语。对比 She gave him a ticket:him is a ticket 说不通,那是\"给人 + 物\"的双宾语。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l01',5,'am2_l01_gp6','choice','{"stem":"把 \"He likes the play.\" 变否定:","options":["He doesn''t like the play.","He isn''t like the play.","He not likes the play.","He don''t like the play."],"answer_index":0,"explanation_cn":"like 是实义动词,否定要借 does + not:✓ He doesn''t like the play. 主语 He 是第三人称单数用 doesn''t;易错:doesn''t 后面动词回到原形 like,不是 likes。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l01',5,'am2_l01_gp6','choice','{"stem":"下列哪个否定式没有缩写形式?","options":["cannot","is not","do not","am not"],"answer_index":3,"explanation_cn":"is not→isn''t、do not→don''t、cannot→can''t 都有缩写,唯独 am not 没有标准缩写,只能说 I''m not。✓ I''m not tired.(没有 amn''t 这种词)"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l01',5,'am2_l01_gp7','choice','{"stem":"把 \"You saw the play.\" 变一般疑问句:","options":["Do you saw the play?","Did you see the play?","Are you see the play?","Saw you the play?"],"answer_index":1,"explanation_cn":"saw 是实义动词的过去形式,变问句要借 Did 开头,动词回到原形 see:✓ Did you see the play? 易错:不说 Did you saw。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l01',5,'am2_l01_gp7','choice','{"stem":"\"Is this your seat?\" 的正确肯定回答:","options":["Yes, it is.","Yes, is it.","Yes, this is.","Yes, it''s."],"answer_index":0,"explanation_cn":"用 Is 问就用 is 答:✓ Yes, it is. 注意肯定简答必须完整说 it is,不能缩写成 Yes, it''s。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l01',5,'am2_l01_gp8','choice','{"stem":"\"___ do you go to the theater?\"(答:By subway.)","options":["Where","How","When","Who"],"answer_index":1,"stem_cn":"你怎么去剧院?","explanation_cn":"回答 By subway.(坐地铁)说的是方式,问方式用 How:✓ How do you go to the theater?(你怎么去剧院)"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l01',5,'am2_l01_gp8','choice','{"stem":"对 \"The couple sat behind me\" 中的 behind me 提问:","options":["Where did the couple sit?","How did the couple sit?","Why did the couple sit?","When did the couple sit?"],"answer_index":0,"explanation_cn":"behind me(在我身后)说的是地点,对地点提问用 Where:✓ Where did the couple sit?(那对情侣坐在哪儿)"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l01',5,'am2_l01_gp9','choice','{"stem":"\"___ seat is this? It''s mine.\"","options":["Which","Who","What","Whose"],"answer_index":3,"stem_cn":"这是谁的座位?是我的。","explanation_cn":"回答 It''s mine.(是我的)说的是\"归谁\",问归属用 Whose + 名词:✓ Whose seat is this?(这是谁的座位)。Which 是\"哪一个\"(供挑选),对不上这个回答。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l01',5,'am2_l01_gp10','choice','{"stem":"\"___ do you go to the theater?\"(答:Three times a year.)","options":["How often","How much","How long","How far"],"answer_index":0,"stem_cn":"你多久去一次剧院?","explanation_cn":"回答 Three times a year.(一年三次)是频率,问频率用 How often:✓ How often do you go to the theater?(你多久去一次剧院)"}'::jsonb,19) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l01',5,'am2_l01_gp10','choice','{"stem":"\"How ___ is the theater from here?\"(答:About two miles.)","options":["tall","old","far","many"],"answer_index":2,"stem_cn":"剧院离这儿有多远?","explanation_cn":"回答 About two miles.(大约两英里)是距离,问距离用 How far:✓ How far is the theater from here?(剧院离这儿多远)"}'::jsonb,20) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l01',5,'am2_l01_gp11','choice','{"stem":"I looked at ___ angrily.(指那对情侣)","options":["their","theirs","they","them"],"answer_index":3,"stem_cn":"我生气地看着他们。","explanation_cn":"动作 looked at 落在\"他们\"身上,要用宾格 them:✓ I looked at them. they 是主格(只能做主语),介词 at 后面必须用宾格。"}'::jsonb,21) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l01',5,'am2_l01_gp11','choice','{"stem":"\"pay no attention\" = \"not pay ___ attention\"","options":["a","much","any","some"],"answer_index":2,"stem_cn":"一点都不理会(pay no attention = not pay any attention)。","explanation_cn":"\"毫不理会\"两种说法等价:paid no attention = didn''t pay any attention。规律:no + 名词 = not…any + 名词。✓ They didn''t pay any attention."}'::jsonb,22) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l01',6,NULL,'choice','{"stem":"\"剧院\" 的美式拼写是:","options":["theator","theatre","theatr","theater"],"answer_index":3,"explanation_cn":"美式拼写是 theater(-er 结尾),英式才写 theatre。✓ We went to the theater. 本课课文用的就是美式拼法。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l01',6,NULL,'choice','{"stem":"\"转过身\" 的地道美语说法是:","options":["turn around","turn about","turn back","turn round"],"answer_index":0,"explanation_cn":"美语\"转身\"说 turn around,英式才说 turn round。易混:turn back 是\"往回走/返回\",意思不一样。✓ I turned around and looked at them."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l01',6,NULL,'choice','{"stem":"语块 get angry 的意思是:","options":["惊讶","生气","高兴","害怕"],"answer_index":1,"explanation_cn":"get angry = 生气。get 在这里表示\"变得\"(从不生气变成生气)。✓ I got angry because I couldn''t hear the actors.(课文原句)\r\n顺带记:高兴 = be happy;害怕 = be afraid;惊讶 = be surprised."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l01',6,NULL,'choice','{"stem":"\"in the end\" 的意思是:","options":["最后,终于","从头开始","在结尾的位置","立刻,马上"],"answer_index":0,"explanation_cn":"in the end = 最后/终于(说事情的结局)。✓ In the end I couldn''t bear it. 易混:at the end (of…) 是\"在…的末尾位置\",两者别搞混。\r\n顺带记:在结尾的位置 = at the end;立刻,马上 = at once / right away;从头开始 = from the start."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l01',6,NULL,'choice','{"stem":"语块 pay attention (to) 的意思是:","options":["道歉","付钱","参加","注意,留心"],"answer_index":3,"explanation_cn":"pay attention (to) = 注意/留心。pay 在这里不是\"付钱\",这是固定搭配,整个记。✓ They didn''t pay any attention.(他们毫不理会——课文原句)\r\n顺带记:付钱 = pay;参加 = take part in / join;道歉 = apologize."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l01',6,NULL,'choice','{"stem":"\"我受不了了!\" 更常用的美语口语说法是:","options":["I can''t carry it!","I can''t stand it!","I can''t sit it!","I can''t stay it!"],"answer_index":1,"explanation_cn":"美语口语\"受不了\"更常说 can''t stand it(can''t bear 也对,偏书面,课文里用的是 couldn''t bear it)。stand 在这里是\"忍受\",不是\"站着\"。✓ I can''t stand the noise!"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l01',7,NULL,'cloze','{"stem":"第 1 空","context":"Last Friday I went to the ___1___ downtown. A young couple was sitting ___2___ me, and they were talking ___3___. I turned around and looked at ___4___, but they didn''t pay any attention.","blank_no":1,"options":["theater","theatre","seat","play"],"answer_index":0,"explanation_cn":"美式拼写是 theater(-er 结尾),英式才写 theatre。本课课文用美语:✓ I went to the theater downtown.\r\n✗ theatre:英式拼法,美语课文用 theater;✗ seat:意思是\"座位\",go to the seat 不通;✗ play:意思是\"戏\",go to the play 不搭配."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l01',7,NULL,'cloze','{"stem":"第 2 空","context":"Last Friday I went to the ___1___ downtown. A young couple was sitting ___2___ me, and they were talking ___3___. I turned around and looked at ___4___, but they didn''t pay any attention.","blank_no":2,"options":["in front of","behind","next","under"],"answer_index":1,"explanation_cn":"那对情侣坐在\"我\"身后,\"在…后面\"用 behind:✓ sitting behind me。in front of 是\"在…前面\",方向正相反。\r\n✗ in front of:意思相反(在前面),课文是坐在后面;✗ next:表方位要说 next to,单独 next 不对;✗ under:\"在…下面\",不合语境."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l01',7,NULL,'cloze','{"stem":"第 3 空","context":"Last Friday I went to the ___1___ downtown. A young couple was sitting ___2___ me, and they were talking ___3___. I turned around and looked at ___4___, but they didn''t pay any attention.","blank_no":3,"options":["loudness","loudly","aloud","louder"],"answer_index":1,"explanation_cn":"说\"说话说得大声\",修饰动词 talking 要用副词 loudly:✓ talking loudly。loud 是形容词,描述人或声音本身,不修饰动作。\r\n✗ loudness:名词\"响度\",这里要副词修饰 talking;✗ aloud:意为\"出声地(读)\",不表\"大声吵闹\";✗ louder:比较级,这句不是在作比较."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l01',7,NULL,'cloze','{"stem":"第 4 空","context":"Last Friday I went to the ___1___ downtown. A young couple was sitting ___2___ me, and they were talking ___3___. I turned around and looked at ___4___, but they didn''t pay any attention.","blank_no":4,"options":["they","their","them","theirs"],"answer_index":2,"explanation_cn":"looked at 后面是动作的对象,用宾格 them(他们):✓ looked at them。they 是主格,只能放在主语位置。\r\n✗ they:主格,介词 at 后面要用宾格;✗ their:形容词性物主代词,后面得接名词;✗ theirs:名词性物主代词,意思对不上."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l01',8,NULL,'choice','{"stem":"Where did the writer go last Friday?","options":["The theater","A restaurant","A concert","The movies"],"answer_index":0,"explanation_cn":"听开头第一句:I went to the theater downtown.(我去了市中心的剧院)。注意别选 the movies——看电影和看戏是两个地方,课文里看的是 play(戏)。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l01',8,NULL,'choice','{"stem":"Why did the writer get angry?","options":["The play was boring","It was too cold","A couple talked loudly","The seat was bad"],"answer_index":2,"explanation_cn":"生气的原因在中段:一对情侣坐在身后 talking loudly the whole time(全程大声说话),吵得\"我\"听不见演员。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l01',8,NULL,'choice','{"stem":"What did the young man say to the writer?","options":["I''m sorry.","Have a good one.","Thank you.","It''s none of your business."],"answer_index":3,"explanation_cn":"结尾处年轻男人粗鲁地回了一句:It''s none of your business.(不关你的事)。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l01',9,NULL,'choice','{"stem":"剧院里有人在你身后大声聊天,你想让他们安静,礼貌的说法是:","options":["Shut up!","I can''t hear a word!","It''s none of your business!","Excuse me, could you please keep it down?"],"answer_index":3,"explanation_cn":"想请别人小声点,礼貌的说法是 Excuse me, could you please keep it down?(不好意思,能小点声吗)。Shut up! 和 It''s none of your business! 都很冲,剧院里这么说会起冲突。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l01',9,NULL,'choice','{"stem":"别人问起你不想透露的私事,你想婉拒:","options":["Turn around.","Have a good one.","I''d rather not say.","Pay attention!"],"answer_index":2,"explanation_cn":"不想透露私事时,婉拒说 I''d rather not say.(我不太想说)——既守住隐私又不失礼。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l01',9,NULL,'choice','{"stem":"你没听清对方的话,想请他再说一遍:","options":["I got angry.","Sorry, I couldn''t hear you — could you say that again?","It''s none of your business.","This is a private conversation."],"answer_index":1,"explanation_cn":"没听清对方的话,请对方重复:Sorry, I couldn''t hear you — could you say that again?(抱歉没听清,能再说一遍吗)。这是日常请人重复的标准说法。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l01',10,NULL,'choice','{"stem":"\"生气地\" 对应的英文单词是:","options":["loudly","angrily","rudely","angry"],"answer_index":1,"explanation_cn":"\"生气地\"说话,修饰动词要用副词 angrily。angry 是形容词\"生气的\"(描述人),带 -ly 的 angrily 才是\"生气地\"(描述动作)。\r\n顺带记:angry = 生气的;loudly = 大声地;rudely = 无礼地."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l01',10,NULL,'choice','{"stem":"课文里 \"I couldn''t bear it\" 中 bear 的意思是:","options":["一种动物","出生","携带","忍受,容忍"],"answer_index":3,"explanation_cn":"课文里 I couldn''t bear it. = 我忍不了了,bear 在这里是\"忍受/容忍\"。bear 还有\"熊\"的意思,但放进这句话讲不通——一词多义要看语境。\r\n顺带记:一种动物 = a bear(熊);携带 = carry;出生 = be born."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l01',10,NULL,'choice','{"stem":"\"They paid attention.\" 的正确否定形式是:","options":["They didn''t paid attention.","They didn''t pay attention.","They not pay attention.","They don''t paid attention."],"answer_index":1,"explanation_cn":"paid 是实义动词的过去形式,变否定借 didn''t,动词回到原形 pay:✓ They didn''t pay attention. 易错:不说 didn''t paid。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l01',10,NULL,'choice','{"stem":"\"The play was funny.\" 的正确一般疑问句是:","options":["The play was funny?","Was funny the play?","Did the play be funny?","Was the play funny?"],"answer_index":3,"explanation_cn":"句子里有 be 动词 was,变问句直接把 was 提到句首:✓ Was the play funny? 有 be 动词就不用再借 Did。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l01',10,NULL,'choice','{"stem":"有人无礼地对你说 \"It''s none of your business.\",意思是:","options":["他在做生意","让你别多管闲事","欢迎你参与","他想和你谈话"],"answer_index":1,"explanation_cn":"It''s none of your business. = 不关你的事/别多管闲事。语气比较冲,别人这么说是在拒绝你过问他的事。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l01',10,NULL,'choice','{"stem":"\"I can''t hear a word!\" 表达的是:","options":["声音太小需要道歉","想学新单词","一个字都听不见","不识字"],"answer_index":2,"explanation_cn":"I can''t hear a word! 直译是\"一个字都听不见\"。not…a word 是\"一点都不/完全不\"的强调说法,表示完全听不清,不是真的在数单词。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l01',10,NULL,'choice','{"stem":"Where did the young couple sit?","options":["Behind the writer.","On the stage.","In front of the writer.","Next to the actors."],"answer_index":0,"passage":"Last Friday I went to the theater downtown. I had a great seat, right in the center. The play was a comedy, and it was really funny. But I didn''t enjoy it at all. A young couple was sitting behind me, and they were talking loudly the whole time. I got angry because I couldn''t hear the actors. I turned around and looked at them, but they didn''t pay any attention. In the end I couldn''t bear it. I turned around again. \"I can''t hear a word!\" I said angrily. \"It''s none of your business,\" the young man said rudely. \"This is a private conversation!\"","explanation_cn":"课文原句:A young couple was sitting behind me.(一对年轻情侣坐在\"我\"身后)。behind = 在…后面。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l01',10,NULL,'choice','{"stem":"Why didn''t the writer enjoy the play?","options":["The play was boring.","He arrived late.","He couldn''t hear the actors.","The seat was bad."],"answer_index":2,"passage":"Last Friday I went to the theater downtown. I had a great seat, right in the center. The play was a comedy, and it was really funny. But I didn''t enjoy it at all. A young couple was sitting behind me, and they were talking loudly the whole time. I got angry because I couldn''t hear the actors. I turned around and looked at them, but they didn''t pay any attention. In the end I couldn''t bear it. I turned around again. \"I can''t hear a word!\" I said angrily. \"It''s none of your business,\" the young man said rudely. \"This is a private conversation!\"","explanation_cn":"课文说 But I didn''t enjoy it at all(一点也没看尽兴),原因是 I couldn''t hear the actors(听不见演员说词)。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l01',10,NULL,'choice','{"stem":"How did the writer feel during the play?","options":["Angry.","Happy.","Scared.","Bored."],"answer_index":0,"audio":"Last Friday I went to the theater downtown. I had a great seat, right in the center. The play was a comedy, and it was really funny. But I didn''t enjoy it at all. A young couple was sitting behind me, and they were talking loudly the whole time. I got angry because I couldn''t hear the actors. I turned around and looked at them, but they didn''t pay any attention. In the end I couldn''t bear it. I turned around again. \"I can''t hear a word!\" I said angrily. \"It''s none of your business,\" the young man said rudely. \"This is a private conversation!\"","explanation_cn":"听关键句:I got angry because I couldn''t hear the actors.(我很生气,因为听不见演员)。got angry = 变得生气。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l01',10,NULL,'choice','{"stem":"What kind of play was it?","options":["A musical.","A mystery.","A comedy.","A tragedy."],"answer_index":2,"audio":"Last Friday I went to the theater downtown. I had a great seat, right in the center. The play was a comedy, and it was really funny. But I didn''t enjoy it at all. A young couple was sitting behind me, and they were talking loudly the whole time. I got angry because I couldn''t hear the actors. I turned around and looked at them, but they didn''t pay any attention. In the end I couldn''t bear it. I turned around again. \"I can''t hear a word!\" I said angrily. \"It''s none of your business,\" the young man said rudely. \"This is a private conversation!\"","explanation_cn":"听第三句:The play was a comedy, and it was really funny.(那出戏是喜剧,非常好笑)。comedy = 喜剧。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am2_l02',2,1,2,'Breakfast or lunch?','早餐还是午餐?','一般现在时 vs 现在进行时 · V-ing拼写 · 频度副词 · What/How感叹句','懒觉的周日 · 姑妈来电,"一点钟还在吃早餐"','{"q":"Listen and answer — Why is the writer''s aunt surprised?","options":["He is still sleeping","He is still having breakfast at one o''clock","He is not at home","He is late for the train"],"answer_index":1}'::jsonb,'{"title":"现在的两种时态(用本课句子看懂它)","intro":"本课要分清两种\"现在\":经常做的事,还是此刻正在做的事。下面全用本课句子举例。","table":{"headers":["时态","什么时候用 · 本课例子"],"rows":[["一般现在时(动词原形 / 第三人称 +s)","说经常、习惯、每天的事:I never get up early on Sundays.(周日从不早起=习惯)"],["一般现在时也说客观事实","The sun rises in the east.(太阳东升=永远的事实)"],["现在进行时(am/is/are + V-ing)","说此刻正在做的事:I''m having breakfast.(此刻正在吃)"],["现在进行时也说近期安排","I''m coming over tonight.(近期打算来=已安排好)"]]},"specialRules":[{"rule":"V-ing 拼写:一般直接加 -ing;去掉不发音的 e(have→having);重读闭音节末尾单辅音字母双写(run→running);ie→y(lie→lying)","mark":"拼写"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l02',1,NULL,'It was Sunday, and I was still fast asleep.','那是个星期天,我还在呼呼大睡。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l02',2,NULL,'I never get up early on Sundays — I usually stay in bed until noon.','周日我从来不早起——通常会赖床到中午。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l02',3,NULL,'That morning it was raining, and it was dark outside.','那天早上在下雨,外面一片昏暗。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l02',4,NULL,'"What a lazy Sunday!" I thought.','"多懒的一个周日啊!"我心想。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l02',5,NULL,'Then my cell phone rang.','这时我的手机响了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l02',6,NULL,'It was my aunt Kate; I''m her only nephew, so she calls me every weekend.','是我姑妈凯特;我是她唯一的外甥,所以她每个周末都给我打电话。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l02',7,NULL,'"I just arrived by train," she said. "I''m coming over to see you right now!"','"我刚坐火车到,"她说,"我这就过来看你!"') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l02',8,NULL,'"But I''m still having breakfast," I said.','"可我还在吃早餐呢,"我说。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l02',9,NULL,'"Breakfast? What are you doing?" she asked.','"早餐?你在干什么?"她问道。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l02',10,NULL,'"I''m having breakfast," I repeated.','"我在吃早餐,"我又说了一遍。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l02',11,NULL,'"Oh my!" she said. "Do you always get up this late? It''s already one o''clock!"','"天哪!"她说,"你总是起这么晚吗?已经一点钟了!"') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l02',12,NULL,'For me, breakfast is the first meal of the day — even at lunchtime.','对我来说,早餐是一天的第一顿饭——哪怕在午饭时间吃。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
