INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l02',5,'am2_l02_gp1','choice','{"stem":"说\"周日的习惯\",选正确的句子:","options":["I never got up early on Sundays.","I never getting up early on Sundays.","I am never getting up early on Sundays.","I never get up early on Sundays."],"answer_index":3,"explanation_cn":"说\"周日的习惯\"用一般现在时(动词原形 get up),不用进行时也不用过去时。✓ I never get up early on Sundays. 频度副词 never 放在实义动词 get 前面。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l02',5,'am2_l02_gp1','choice','{"stem":"\"She ___ me every weekend.\"(每周都打来的习惯)","options":["calls","call","is calling","called"],"answer_index":0,"stem_cn":"她每周都给我打电话。","explanation_cn":"\"每周都打来\"是习惯,用一般现在时;主语 She 是第三人称单数,动词加 -s → calls。✓ She calls me every weekend."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l02',5,'am2_l02_gp2','choice','{"stem":"\"The sun ___ in the east and ___ in the west.\"(客观事实)","options":["rise / set","rose / set","rises / sets","is rising / is setting"],"answer_index":2,"stem_cn":"太阳从东边升起,从西边落下。","explanation_cn":"太阳东升西落是客观事实,永远用一般现在时;主语 the sun 第三人称单数,动词加 -s。✓ The sun rises in the east and sets in the west."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l02',5,'am2_l02_gp3','choice','{"stem":"\"Look outside! It ___ right now.\"(此刻正在下)","options":["rains","rained","rain","is raining"],"answer_index":3,"stem_cn":"快看外面!现在正在下雨。","explanation_cn":"\"right now\"表示此刻正在下,用现在进行时 be+V-ing → is raining。✓ It is raining right now. 一般现在时 rains 说的是\"经常下\",对不上\"此刻\"。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l02',5,'am2_l02_gp3','choice','{"stem":"\"What ___ you ___ now?\" — \"I''m having breakfast.\"","options":["are / doing","did / do","are / do","do / do"],"answer_index":0,"stem_cn":"你现在在做什么?——我在吃早餐。","explanation_cn":"问\"此刻正在做什么\"用现在进行时:What are you doing? 主语 you 配 are,动词加 -ing → doing。✓ 回答也用进行时:I''m having breakfast."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l02',5,'am2_l02_gp4','choice','{"stem":"\"run\" 的现在进行时:He is ___ to the station.","options":["runing","runnning","runy","running"],"answer_index":3,"explanation_cn":"run 是重读闭音节、末尾单个辅音字母 n,变现在分词要双写 n 再加 -ing → running。✓ He is running to the station."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l02',5,'am2_l02_gp4','choice','{"stem":"下面哪个是 \"have\" 的正确现在分词(V-ing)?","options":["having","haveing","haing","havving"],"answer_index":0,"explanation_cn":"have 以不发音的 e 结尾,变现在分词先去掉 e 再加 -ing → having。✓ I''m having breakfast. 不能写成 haveing。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l02',5,'am2_l02_gp5','choice','{"stem":"\"I''m coming over to see you tonight.\" 这句话表示:","options":["我经常来看你","我现在正在路上","我昨天来看过你","我近期打算/安排来看你"],"answer_index":3,"explanation_cn":"现在进行时除了\"此刻正在做\",还能表示近期已安排好的事。I''m coming over tonight = 今晚我打算/安排过来,不是此刻正在路上。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l02',5,'am2_l02_gp6','choice','{"stem":"下列哪句在说\"此刻正在做的事\"?","options":["She reads the news every morning.","The earth moves around the sun.","I''m having breakfast right now.","I get up at noon on Sundays."],"answer_index":2,"explanation_cn":"\"此刻正在做的事\"要用现在进行时(be+V-ing)。只有 I''m having breakfast right now 是进行时;其它几句(get up on Sundays / reads every morning / earth moves)都是一般现在时,说的是习惯或事实。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l02',5,'am2_l02_gp6','choice','{"stem":"\"He ___ to work by subway every day, but today he ___ the bus.\"","options":["goes / is taking","go / take","is going / takes","is going / is taking"],"answer_index":0,"stem_cn":"他每天坐地铁上班,但今天他改乘公交车。","explanation_cn":"\"every day\"是习惯用一般现在时 goes;\"today\"此刻改用现在进行时 is taking。✓ He goes to work by subway every day, but today he is taking the bus. 一句里两种时态各管一段。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l02',5,'am2_l02_gp6','choice','{"stem":"\"Be quiet! The baby ___.\"(此刻)","options":["sleeps","slept","sleep","is sleeping"],"answer_index":3,"stem_cn":"安静!宝宝在睡觉。","explanation_cn":"\"Be quiet!\"提示此刻正在睡,用现在进行时 is sleeping。✓ The baby is sleeping. 一般现在时 sleeps 说的是\"平时睡\",对不上此刻。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l02',5,'am2_l02_gp7','choice','{"stem":"下面哪句 always 的位置正确?","options":["She always gets up late.","She gets up late always.","She gets always up late.","Gets up she always late."],"answer_index":0,"explanation_cn":"频度副词 always 放在实义动词 gets 前面。✓ She always gets up late. 不能塞进 gets up 中间,也不能放句尾。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l02',5,'am2_l02_gp7','choice','{"stem":"频度副词(always/never/usually)在句中一般放在什么位置?","options":["宾语后面","句子最后面","实义动词前、be 动词后","句子最前面"],"answer_index":2,"explanation_cn":"频度副词(always/never/usually)的位置规则:实义动词前(I always get up late)、be 动词或助动词后(I am always late)。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l02',5,'am2_l02_gp8','choice','{"stem":"\"___ a rainy day!\"(感叹\"多雨/糟糕的一天\")","options":["Which","How","Very","What"],"answer_index":3,"stem_cn":"多糟糕的雨天啊!","explanation_cn":"感叹\"多…的一天\",day 是名词,用 What 引导:What a rainy day! What 后面接名词短语。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l02',5,'am2_l02_gp8','choice','{"stem":"\"___ fast time flies!\"(感叹时间过得快)","options":["How","How a","What a","What"],"answer_index":0,"stem_cn":"时间过得真快啊!","explanation_cn":"感叹\"时间过得多快\",fast 是副词,用 How 引导:How fast time flies! How 后面接形容词或副词。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l02',5,'am2_l02_gp8','choice','{"stem":"\"It''s a beautiful garden.\" 改成 What 感叹句:","options":["How a beautiful garden it is!","What beautiful a garden it is!","What a beautiful garden is it!","What a beautiful garden it is!"],"answer_index":3,"explanation_cn":"What 感叹句结构:What + a + 形容词 + 可数名词单数 + 主谓!→ What a beautiful garden it is! 冠词 a 紧跟 What,主谓 it is 放最后。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l02',5,'am2_l02_gp9','choice','{"stem":"\"I stayed up late, so I went ___ bed after midnight.\"(上床睡觉)","options":["on","to","in","at"],"answer_index":1,"stem_cn":"我熬夜了,所以过了午夜才上床睡觉。","explanation_cn":"\"上床睡觉\"是固定搭配 go to bed,介词用 to。✓ I went to bed after midnight."}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l02',5,'am2_l02_gp9','choice','{"stem":"\"He doesn''t get up early. He gets up ___.\"(起得晚)","options":["late","lateness","lately","later"],"answer_index":0,"stem_cn":"他不早起,他起得晚。","explanation_cn":"\"起得晚\"用 late(这里作副词修饰 get up)。✓ He gets up late. 易错:lately 意思是\"最近\",不是\"晚\"。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l02',6,NULL,'choice','{"stem":"语块 get up 的意思是:","options":["坐下","出门","起床","睡觉"],"answer_index":2,"explanation_cn":"get up = 起床(从床上起来)。✓ I get up at seven. 和 stay in bed(赖床)正好相反。\r\n顺带记:睡觉 = go to bed / sleep;坐下 = sit down;出门 = go out."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l02',6,NULL,'choice','{"stem":"语块 stay in bed 的意思是:","options":["换床单","赖床/待在床上","起床","铺床"],"answer_index":1,"explanation_cn":"stay in bed = 待在床上、赖床不起。✓ I stay in bed until noon on Sundays.\r\n顺带记:铺床 = make the bed;起床 = get up;换床单 = change the sheets."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l02',6,NULL,'choice','{"stem":"\"我这就过来看你\" 用哪个语块?","options":["come over","go over","come up","come out"],"answer_index":0,"explanation_cn":"come over = (到某人那儿)过来、串门。✓ I''m coming over to see you. 想说\"我这就过来\"就用它。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l02',6,NULL,'choice','{"stem":"\"手机\" 的美语常用说法是:","options":["mobile","cell phone","hand machine","telephone box"],"answer_index":1,"explanation_cn":"美语\"手机\"常说 cell phone,或直接 phone;英式说 mobile。✓ My cell phone rang."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l02',6,NULL,'choice','{"stem":"\"假期\" 的美语说法是:","options":["festival","weekend","holiday","vacation"],"answer_index":3,"explanation_cn":"美语\"假期\"说 vacation;英式说 holiday。✓ We''re on vacation.(我们在度假)。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l02',6,NULL,'choice','{"stem":"\"旅行(travel)\" 的现在分词美式拼写是:","options":["traveleing","travling","traveling","travelling"],"answer_index":2,"explanation_cn":"travel 变现在分词,美式拼写单 l → traveling;英式双 l → travelling。✓ We''re traveling to New York."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l02',7,NULL,'cloze','{"stem":"第 1 空","context":"It was Sunday. I never ___1___ early on Sundays. That morning my aunt Kate called. \"I ___2___ over to see you,\" she said. \"But I ___3___ breakfast,\" I said. She was surprised. \"___4___ a lazy Sunday!\"","blank_no":1,"options":["get up","am getting up","got up","getting up"],"answer_index":0,"explanation_cn":"\"周日从不早起\"是习惯,用一般现在时原形 get up(前面有频度副词 never)。✓ I never get up early on Sundays.\r\n✗ am getting up:never 表习惯用一般现在时,不用现在进行;✗ got up:说的是习惯,不是过去;✗ getting up:缺助动词,单独不能作谓语."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l02',7,NULL,'cloze','{"stem":"第 2 空","context":"It was Sunday. I never ___1___ early on Sundays. That morning my aunt Kate called. \"I ___2___ over to see you,\" she said. \"But I ___3___ breakfast,\" I said. She was surprised. \"___4___ a lazy Sunday!\"","blank_no":2,"options":["come","''m coming","came","comes"],"answer_index":1,"explanation_cn":"\"我这就过来看你\"是近期安排,用现在进行时 → I''m coming over。表示已经打算好的事。\r\n✗ come:表最近安排的\"这就过来\"用现在进行 ''m coming;✗ came:不是过去;✗ comes:主语 I 不用第三人称 comes,这里也该用进行时."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l02',7,NULL,'cloze','{"stem":"第 3 空","context":"It was Sunday. I never ___1___ early on Sundays. That morning my aunt Kate called. \"I ___2___ over to see you,\" she said. \"But I ___3___ breakfast,\" I said. She was surprised. \"___4___ a lazy Sunday!\"","blank_no":3,"options":["have","''m having","had","has"],"answer_index":1,"explanation_cn":"\"此刻还在吃早餐\"用现在进行时 → I''m having breakfast。still + 进行时强调\"仍在进行\"。\r\n✗ have:此刻正在吃,用现在进行 ''m having;✗ had:不是过去;✗ has:主语 I 不用 has."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l02',7,NULL,'cloze','{"stem":"第 4 空","context":"It was Sunday. I never ___1___ early on Sundays. That morning my aunt Kate called. \"I ___2___ over to see you,\" she said. \"But I ___3___ breakfast,\" I said. She was surprised. \"___4___ a lazy Sunday!\"","blank_no":4,"options":["How","What","Which","Very"],"answer_index":1,"explanation_cn":"感叹\"多懒的一个周日\",Sunday 是名词,用 What 引导 → What a lazy Sunday!\r\n✗ How:后面是名词短语 a lazy Sunday,感叹名词用 What a…;✗ Which:意为\"哪一个\",不是感叹;✗ Very:不能引导感叹句."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l02',8,NULL,'choice','{"stem":"What day is it?","options":["Friday","Monday","Sunday","Saturday"],"answer_index":2,"explanation_cn":"听开头 It was Sunday(那是个星期天),所以这天是周日。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l02',8,NULL,'choice','{"stem":"Who is calling the writer?","options":["His aunt","His mom","His boss","His friend"],"answer_index":0,"explanation_cn":"听到 It was my aunt Kate(是我姑妈凯特),打电话来的是他姑妈。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l02',8,NULL,'choice','{"stem":"Why is the aunt surprised?","options":["He missed the train","He is still asleep","It''s raining","He is having breakfast at one o''clock"],"answer_index":3,"explanation_cn":"姑妈惊讶是因为已经一点钟了他还在吃早餐(Do you always get up this late? It''s already one o''clock!)。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l02',9,NULL,'choice','{"stem":"朋友周日早上打来,你还在睡,想说\"我周日从不早起\":","options":["I never get up early on Sundays.","I''m getting up now.","I got up early today.","I always get up early."],"answer_index":0,"explanation_cn":"想说\"我周日从不早起\"这个习惯,用一般现在时 + never。✓ I never get up early on Sundays. 场合:跟人聊自己的作息习惯。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l02',9,NULL,'choice','{"stem":"你此刻正在吃早餐,别人问 \"What are you doing?\",你回答:","options":["I have breakfast every day.","I will have breakfast.","I''m having breakfast.","I had breakfast."],"answer_index":2,"explanation_cn":"别人问\"你在干什么\"(此刻),回答用现在进行时说正在做的事。✓ I''m having breakfast. 场合:描述此刻正在进行的动作。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l02',9,NULL,'choice','{"stem":"姑妈说这就过来,你想表达\"我这就过来看你\"的地道美语:","options":["I''m come over.","I''m coming over to see you.","I come over you.","I came over you."],"answer_index":1,"explanation_cn":"\"我这就过来看你\"用现在进行时表近期安排 + 语块 come over。✓ I''m coming over to see you. 场合:告诉对方你马上要过去。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l02',10,NULL,'choice','{"stem":"\"外面\" 对应的英文单词是:","options":["outdoors","inside","outside","outer"],"answer_index":2,"explanation_cn":"\"外面\"对应 outside。✓ It was dark outside. inside 是\"里面\",方向相反。\r\n顺带记:inside = 里面;outdoors = 户外(地);outer = 外部的."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l02',10,NULL,'choice','{"stem":"课文里 \"the first meal of the day\" 中 meal 的意思是:","options":["一餐,一顿饭","心情","时间","面粉"],"answer_index":0,"explanation_cn":"meal = 一餐、一顿饭。✓ Breakfast is the first meal of the day.(早餐是一天的第一顿饭)。\r\n顺带记:面粉 = flour;时间 = time;心情 = mood."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l02',10,NULL,'choice','{"stem":"\"Look! It ___ outside now.\"(此刻正在下雨)","options":["rains","rain","is raining","rained"],"answer_index":2,"stem_cn":"快看!外面正在下雨。","explanation_cn":"\"now\"此刻正在下雨,用现在进行时 is raining。✓ It is raining outside now."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l02',10,NULL,'choice','{"stem":"\"I ___ early on Sundays.\"(周日的习惯:从不早起)","options":["am never getting up","never get up","never getting up","never got up"],"answer_index":1,"stem_cn":"周日我从不早起。","explanation_cn":"\"周日从不早起\"是习惯,用一般现在时原形 get up,频度副词 never 放动词前。✓ I never get up early on Sundays."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l02',10,NULL,'choice','{"stem":"姑妈看到你一点还在吃早餐,惊讶地说 \"Oh my!\",意思是:","options":["她很生气","她在打招呼","表示惊讶/意外(天哪)","她要走了"],"answer_index":2,"explanation_cn":"Oh my! 是表示惊讶、意外的感叹,相当于中文\"天哪!\"。场合:看到意想不到的事时脱口而出。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l02',10,NULL,'choice','{"stem":"\"What a lazy Sunday!\" 表达的是:","options":["询问星期几","命令别人起床","抱怨天气很冷","感叹这个周日真慵懒"],"answer_index":3,"explanation_cn":"What a lazy Sunday! 是感叹句,感叹\"这个周日真懒散/慵懒\",不是在提问。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l02',10,NULL,'choice','{"stem":"What does the writer usually do on Sundays?","options":["He visits his aunt.","He stays in bed until noon.","He goes to work.","He gets up early."],"answer_index":1,"passage":"It was Sunday, and I was still fast asleep. I never get up early on Sundays — I usually stay in bed until noon. That morning it was raining, and it was dark outside. \"What a lazy Sunday!\" I thought. Then my cell phone rang. It was my aunt Kate; I''m her only nephew, so she calls me every weekend. \"I just arrived by train,\" she said. \"I''m coming over to see you right now!\" \"But I''m still having breakfast,\" I said. \"Breakfast? What are you doing?\" she asked. \"I''m having breakfast,\" I repeated. \"Oh my!\" she said. \"Do you always get up this late? It''s already one o''clock!\" For me, breakfast is the first meal of the day — even at lunchtime.","explanation_cn":"课文说 I usually stay in bed until noon(周日通常赖床到中午),所以他周日通常待在床上。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l02',10,NULL,'choice','{"stem":"Why was the aunt surprised?","options":["He was out.","He was asleep.","He missed the train.","He was having breakfast at one o''clock."],"answer_index":3,"passage":"It was Sunday, and I was still fast asleep. I never get up early on Sundays — I usually stay in bed until noon. That morning it was raining, and it was dark outside. \"What a lazy Sunday!\" I thought. Then my cell phone rang. It was my aunt Kate; I''m her only nephew, so she calls me every weekend. \"I just arrived by train,\" she said. \"I''m coming over to see you right now!\" \"But I''m still having breakfast,\" I said. \"Breakfast? What are you doing?\" she asked. \"I''m having breakfast,\" I repeated. \"Oh my!\" she said. \"Do you always get up this late? It''s already one o''clock!\" For me, breakfast is the first meal of the day — even at lunchtime.","explanation_cn":"姑妈惊讶是因为都一点钟了他还在吃早餐(It''s already one o''clock)。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l02',10,NULL,'choice','{"stem":"How does the writer know his aunt has arrived?","options":["She knocks on the door.","She sends a text.","She calls him on the phone.","She emails him."],"answer_index":2,"audio":"It was Sunday, and I was still fast asleep. I never get up early on Sundays — I usually stay in bed until noon. That morning it was raining, and it was dark outside. \"What a lazy Sunday!\" I thought. Then my cell phone rang. It was my aunt Kate; I''m her only nephew, so she calls me every weekend. \"I just arrived by train,\" she said. \"I''m coming over to see you right now!\" \"But I''m still having breakfast,\" I said. \"Breakfast? What are you doing?\" she asked. \"I''m having breakfast,\" I repeated. \"Oh my!\" she said. \"Do you always get up this late? It''s already one o''clock!\" For me, breakfast is the first meal of the day — even at lunchtime.","explanation_cn":"课文里姑妈是打电话来的(my cell phone rang… she said),所以他是通过电话知道姑妈到了。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l02',10,NULL,'choice','{"stem":"What is the weather like that morning?","options":["It''s snowing.","It''s raining.","It''s windy.","It''s sunny."],"answer_index":1,"audio":"It was Sunday, and I was still fast asleep. I never get up early on Sundays — I usually stay in bed until noon. That morning it was raining, and it was dark outside. \"What a lazy Sunday!\" I thought. Then my cell phone rang. It was my aunt Kate; I''m her only nephew, so she calls me every weekend. \"I just arrived by train,\" she said. \"I''m coming over to see you right now!\" \"But I''m still having breakfast,\" I said. \"Breakfast? What are you doing?\" she asked. \"I''m having breakfast,\" I repeated. \"Oh my!\" she said. \"Do you always get up this late? It''s already one o''clock!\" For me, breakfast is the first meal of the day — even at lunchtime.","explanation_cn":"课文说 That morning it was raining(那天早上在下雨),所以那天早上的天气是下雨。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am2_l03',2,1,3,'Please send me a card','请给我寄一张明信片','一般过去时(规则/不规则动词·否定·疑问)· be动词过去式 · lend vs borrow','去意大利度假 · 拖到最后一天买了37张明信片却一张没写','{"q":"Listen and answer — How many cards did the writer send?","options":["None","Thirty-seven","A few","Only one"],"answer_index":0}'::jsonb,'{"title":"说过去发生的事(一般过去时)","intro":"本课讲怎么说\"已经发生过、结束了\"的事。下面全用本课句子举例。","table":{"headers":["用法 / 构成","本课例子"],"rows":[["规则动词:一般 +ed;e结尾 +d;辅音+y→ied;重读闭音节末单辅音双写+ed","I visited museums.(visit→visited)"],["不规则动词:要单独记(go→went / buy→bought / get→got / make→made / read→read)","Last summer I went to Italy.(go→went)"],["否定:didn''t + 动词原形(动词要变回原形)","I didn''t send any cards.(不是 didn''t sent)"],["疑问:Did + 主语 + 动词原形?","Did you go out last night?"],["be 动词过去式:am/is→was,are→were","The weather was warm."]]},"specialRules":[{"rule":"时间状语 last summer / yesterday / … ago / on the last day 前面不加介词(不能说 in last summer)","mark":"时间状语"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l03',1,NULL,'Postcards always spoil my vacations.','明信片总是搅得我假期不得安宁。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l03',2,NULL,'Last summer I went to Italy.','去年夏天我去了意大利。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l03',3,NULL,'I visited a lot of museums and sat in public parks.','我参观了很多博物馆,还在公共公园里坐了坐。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l03',4,NULL,'The museums were free, and the weather was warm.','博物馆免费,天气也暖和。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l03',5,NULL,'A friendly waiter taught me a few words of Italian, and then he lent me a book.','一位友好的服务员教了我几句意大利语,之后还借给我一本书。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l03',6,NULL,'I read a few lines, but I didn''t understand a word.','我读了几行,但一个字也没看懂。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l03',7,NULL,'Every day I thought about the postcards, but I didn''t send any.','我每天都想着明信片的事,却一张也没寄。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l03',8,NULL,'My vacation passed quickly.','假期过得飞快。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l03',9,NULL,'On the last day I made a big decision.','到了最后一天,我下了一个重大决心。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l03',10,NULL,'I got up early and bought thirty-seven postcards.','我早早起床,买了三十七张明信片。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l03',11,NULL,'I spent the whole day in my room, but I didn''t write a single card!','我在房间里待了一整天,却一张明信片也没写成!') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_words (lesson_id,word,ipa,pos,meaning_cn,example) VALUES ('am2_l03','send','/send/','v','寄,送(sent)','I didn''t send any cards.') ON CONFLICT (lesson_id,word) DO UPDATE SET ipa=EXCLUDED.ipa,pos=EXCLUDED.pos,meaning_cn=EXCLUDED.meaning_cn,example=EXCLUDED.example;
INSERT INTO public.american_words (lesson_id,word,ipa,pos,meaning_cn,example) VALUES ('am2_l03','postcard','/ˈpoʊstkɑːrd/','n','明信片','I bought thirty-seven postcards.') ON CONFLICT (lesson_id,word) DO UPDATE SET ipa=EXCLUDED.ipa,pos=EXCLUDED.pos,meaning_cn=EXCLUDED.meaning_cn,example=EXCLUDED.example;
INSERT INTO public.american_words (lesson_id,word,ipa,pos,meaning_cn,example) VALUES ('am2_l03','spoil','/spɔɪl/','v','破坏,使扫兴(spoiled)','Postcards always spoil my vacations.') ON CONFLICT (lesson_id,word) DO UPDATE SET ipa=EXCLUDED.ipa,pos=EXCLUDED.pos,meaning_cn=EXCLUDED.meaning_cn,example=EXCLUDED.example;
INSERT INTO public.american_words (lesson_id,word,ipa,pos,meaning_cn,example) VALUES ('am2_l03','museum','/mjuˈziːəm/','n','博物馆','I visited a lot of museums.') ON CONFLICT (lesson_id,word) DO UPDATE SET ipa=EXCLUDED.ipa,pos=EXCLUDED.pos,meaning_cn=EXCLUDED.meaning_cn,example=EXCLUDED.example;
INSERT INTO public.american_words (lesson_id,word,ipa,pos,meaning_cn,example) VALUES ('am2_l03','public','/ˈpʌblɪk/','adj','公共的','I sat in public parks.') ON CONFLICT (lesson_id,word) DO UPDATE SET ipa=EXCLUDED.ipa,pos=EXCLUDED.pos,meaning_cn=EXCLUDED.meaning_cn,example=EXCLUDED.example;
INSERT INTO public.american_words (lesson_id,word,ipa,pos,meaning_cn,example) VALUES ('am2_l03','friendly','/ˈfrendli/','adj','友好的','A friendly waiter taught me some Italian.') ON CONFLICT (lesson_id,word) DO UPDATE SET ipa=EXCLUDED.ipa,pos=EXCLUDED.pos,meaning_cn=EXCLUDED.meaning_cn,example=EXCLUDED.example;
INSERT INTO public.american_words (lesson_id,word,ipa,pos,meaning_cn,example) VALUES ('am2_l03','waiter','/ˈweɪtər/','n','服务员','The waiter lent me a book.') ON CONFLICT (lesson_id,word) DO UPDATE SET ipa=EXCLUDED.ipa,pos=EXCLUDED.pos,meaning_cn=EXCLUDED.meaning_cn,example=EXCLUDED.example;
INSERT INTO public.american_words (lesson_id,word,ipa,pos,meaning_cn,example) VALUES ('am2_l03','lend','/lend/','v','借给,借出(lent)','He lent me a book.') ON CONFLICT (lesson_id,word) DO UPDATE SET ipa=EXCLUDED.ipa,pos=EXCLUDED.pos,meaning_cn=EXCLUDED.meaning_cn,example=EXCLUDED.example;
INSERT INTO public.american_words (lesson_id,word,ipa,pos,meaning_cn,example) VALUES ('am2_l03','decision','/dɪˈsɪʒn/','n','决定','I made a big decision.') ON CONFLICT (lesson_id,word) DO UPDATE SET ipa=EXCLUDED.ipa,pos=EXCLUDED.pos,meaning_cn=EXCLUDED.meaning_cn,example=EXCLUDED.example;
INSERT INTO public.american_words (lesson_id,word,ipa,pos,meaning_cn,example) VALUES ('am2_l03','whole','/hoʊl/','adj','整个的','I spent the whole day in my room.') ON CONFLICT (lesson_id,word) DO UPDATE SET ipa=EXCLUDED.ipa,pos=EXCLUDED.pos,meaning_cn=EXCLUDED.meaning_cn,example=EXCLUDED.example;
INSERT INTO public.american_words (lesson_id,word,ipa,pos,meaning_cn,example) VALUES ('am2_l03','single','/ˈsɪŋɡl/','adj','唯一的,单一的','I didn''t write a single card.') ON CONFLICT (lesson_id,word) DO UPDATE SET ipa=EXCLUDED.ipa,pos=EXCLUDED.pos,meaning_cn=EXCLUDED.meaning_cn,example=EXCLUDED.example;
