INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am2_l03','mail','post','寄(信/卡);美语 mail a card,英式 post a card;邮箱 mailbox / postbox') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am2_l03','vacation','holiday','假期;承 L2,美语用 vacation') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
