INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l03','lend / borrow','',NULL,'/lend/ /ˈbɑːroʊ/','He lent me a book.','他借给我一本书。(借出)','I borrowed a book from him.','我从他那儿借了一本书。(借入)') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l03','make a decision','',NULL,'/meɪk ə dɪˈsɪʒn/','On the last day I made a big decision.','最后一天我下了个重大决定。','It''s hard to make a decision.','做决定很难。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l03','a few','',NULL,'/ə fjuː/','He taught me a few words of Italian.','他教了我几句意大利语。','I read a few lines.','我读了几行。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l03',5,'am2_l03_gp1','choice','{"stem":"\"I ___ three museums yesterday.\"(visit 的过去式)","options":["visiting","visited","visitted","visit"],"answer_index":1,"explanation_cn":"规则动词过去式:visit 直接加 -ed → visited。✓ I visited three museums yesterday. yesterday 提示这是过去发生的事。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l03',5,'am2_l03_gp1','choice','{"stem":"\"She ___ when she heard the news.\"(cry 的过去式)","options":["cryed","cryied","cried","cries"],"answer_index":2,"explanation_cn":"cry 以\"辅音字母+y\"结尾,变过去式把 y 改成 i 再加 -ed → cried。✓ She cried when she heard the news."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l03',5,'am2_l03_gp2','choice','{"stem":"\"Last summer I ___ to Italy.\"(go 的过去式)","options":["gone","went","going","goed"],"answer_index":1,"explanation_cn":"go 是不规则动词,过去式是 went(不加 -ed)。✓ Last summer I went to Italy.(L1、L2 课文里也见过 went)。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l03',5,'am2_l03_gp2','choice','{"stem":"\"He ___ me a book.\"(lend\"借出\"的过去式)","options":["lends","lend","lended","lent"],"answer_index":3,"explanation_cn":"lend(借出)是不规则动词,过去式 lent。✓ He lent me a book. 别写成 lended。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l03',5,'am2_l03_gp2','choice','{"stem":"\"I ___ thirty-seven cards.\"(buy 的过去式)","options":["bought","boughted","buyed","buys"],"answer_index":0,"explanation_cn":"buy 是不规则动词,过去式 bought。✓ I bought thirty-seven cards. 别写成 buyed。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l03',5,'am2_l03_gp3','choice','{"stem":"\"I read a few lines, but I ___ a word.\"(understand 的否定)","options":["didn''t understood","didn''t understand","don''t understand","not understood"],"answer_index":1,"explanation_cn":"过去时否定用 didn''t + 动词原形,understand 要还原成原形。✓ I didn''t understand a word. 不是 didn''t understood。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l03',5,'am2_l03_gp3','choice','{"stem":"过去时的否定 didn''t 后面,动词要用:","options":["过去式","加 -ing","加 -ed","动词原形"],"answer_index":3,"explanation_cn":"过去时否定 didn''t 本身已经表示过去,后面的动词一律用原形,不再变过去式。✓ didn''t send / didn''t write。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l03',5,'am2_l03_gp4','choice','{"stem":"把 \"You saw the play.\" 变一般过去疑问句:","options":["Did you see the play?","Were you see the play?","Do you see the play?","Did you saw the play?"],"answer_index":0,"explanation_cn":"过去时一般疑问:Did + 主语 + 动词原形。see 要还原原形。✓ Did you see the play? 不是 Did you saw。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l03',5,'am2_l03_gp4','choice','{"stem":"\"Did you go out last night?\" 的正确回答:","options":["Yes, I went.","Yes, I did.","Yes, I was.","Yes, I do."],"answer_index":1,"explanation_cn":"Did…? 的肯定回答用 Yes, 主语 + did。✓ Yes, I did."}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l03',5,'am2_l03_gp5','choice','{"stem":"\"___ cards did he buy?\"(问买了多少张)","options":["What","How long","How many","How much"],"answer_index":2,"explanation_cn":"问\"多少张卡\"(卡可数),用 How many + 可数名词复数。✓ How many cards did he buy?"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l03',5,'am2_l03_gp5','choice','{"stem":"对 \"He stayed in his room.\" 中的 in his room 提问:","options":["Where did he stayed?","Where did he stay?","Where he stayed?","Where was he stay?"],"answer_index":1,"explanation_cn":"对地点提问:Where + did + 主语 + 动词原形。✓ Where did he stay? 不是 Where did he stayed。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l03',5,'am2_l03_gp6','choice','{"stem":"\"___ I went to Italy.\"(去年夏天)","options":["In last summer","On last summer","At last summer","Last summer"],"answer_index":3,"explanation_cn":"\"去年夏天\"直接说 Last summer,前面不加介词。✓ Last summer I went to Italy. 不能说 in last summer。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l03',5,'am2_l03_gp6','choice','{"stem":"下列哪句在说\"已经发生过、结束了\"的事?","options":["The sun rises in the east.","I go to Italy every year.","Last summer I went to Italy.","I''m going to Italy now."],"answer_index":2,"explanation_cn":"\"已经发生过、结束了\"的事用一般过去时。只有 Last summer I went to Italy 是过去时(went);其它几句是一般现在时(说习惯/事实)或现在进行时。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l03',5,'am2_l03_gp7','choice','{"stem":"\"The weather ___ warm, and the people ___ friendly.\"","options":["were / was","was / were","was / was","is / are"],"answer_index":1,"explanation_cn":"be 动词过去式:单数主语(the weather)用 was,复数主语(the people)用 were。✓ The weather was warm, and the people were friendly."}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l03',5,'am2_l03_gp7','choice','{"stem":"\"___ you afraid of the dog?\" — \"No, I wasn''t.\"","options":["Are","Did","Were","Was"],"answer_index":2,"explanation_cn":"回答是 No, I wasn''t,主语 you 对应 were;疑问句把 Were 提到主语前。✓ Were you afraid?"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l03',5,'am2_l03_gp8','choice','{"stem":"\"他借给我一本书\"——lend 是\"借出\"。选正确的:","options":["He borrowed me from a book.","He lent me from a book.","He borrowed me a book.","He lent me a book."],"answer_index":3,"explanation_cn":"lend = 借出(把自己的东西给别人),过去式 lent。✓ He lent me a book. borrow 是\"借入\",方向正相反。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l03',5,'am2_l03_gp8','choice','{"stem":"\"我从图书馆借了一本书\"——\"借入\"用 borrow:","options":["I borrowed the library a book.","I lent a book from the library.","I borrowed a book from the library.","I lent the library a book."],"answer_index":2,"explanation_cn":"borrow = 借入(从别处借来),常用 borrow sth from sb。✓ I borrowed a book from the library."}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l03',5,'am2_l03_gp2','choice','{"stem":"\"I ___ the whole day in my room.\"(spend 的过去式)","options":["spendt","spend","spended","spent"],"answer_index":3,"explanation_cn":"spend 是不规则动词,过去式 spent。✓ I spent the whole day in my room."}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l03',6,NULL,'choice','{"stem":"语块 lend 的意思是:","options":["借出(把东西借给别人)","购买","借入(从别人处借)","出售"],"answer_index":0,"explanation_cn":"lend = 借出:把自己的东西借给别人。✓ He lent me a book. 和 borrow(借入)方向相反。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l03',6,NULL,'choice','{"stem":"make a decision 的意思是:","options":["提问题","改主意","做决定","犯错误"],"answer_index":2,"explanation_cn":"make a decision = 做决定、下决心。✓ I made a big decision."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l03',6,NULL,'choice','{"stem":"a few 的意思是:","options":["没有","很多","一点点(修饰不可数)","几个(修饰可数名词)"],"answer_index":3,"explanation_cn":"a few = 几个,修饰可数名词复数。✓ a few words / a few cards. 修饰不可数名词要用 a little。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l03',6,NULL,'choice','{"stem":"\"寄(明信片)\"的美语常用词是:","options":["drop","post","mail","throw"],"answer_index":2,"explanation_cn":"美语\"寄(信/卡)\"用 mail;英式用 post。✓ I''ll mail the card tomorrow."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l03',6,NULL,'choice','{"stem":"\"假期\"的美语说法是:","options":["vacation","weekend","festival","holiday"],"answer_index":0,"explanation_cn":"美语\"假期\"说 vacation;英式说 holiday。✓ We had a great vacation."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l03',6,NULL,'choice','{"stem":"spoil(破坏)的过去式,美式拼写是:","options":["spoilt","spoild","spoilded","spoiled"],"answer_index":3,"explanation_cn":"spoil 的过去式,美式规则拼写 spoiled;英式 spoilt。✓ The rain spoiled our trip."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l03',7,NULL,'cloze','{"stem":"第 1 空","context":"Last summer I ___1___ to Italy. A friendly waiter ___2___ me a few words of Italian. Every day I ___3___ about postcards, but I ___4___ send any.","blank_no":1,"options":["went","go","goes","going"],"answer_index":0,"explanation_cn":"\"去年夏天去意大利\"用一般过去时,go→went。✓ Last summer I went to Italy."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l03',7,NULL,'cloze','{"stem":"第 2 空","context":"Last summer I ___1___ to Italy. A friendly waiter ___2___ me a few words of Italian. Every day I ___3___ about postcards, but I ___4___ send any.","blank_no":2,"options":["teached","taught","teaches","teaching"],"answer_index":1,"explanation_cn":"teach 是不规则动词,过去式 taught。✓ A waiter taught me some Italian."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l03',7,NULL,'cloze','{"stem":"第 3 空","context":"Last summer I ___1___ to Italy. A friendly waiter ___2___ me a few words of Italian. Every day I ___3___ about postcards, but I ___4___ send any.","blank_no":3,"options":["think","thought","thinks","thinking"],"answer_index":1,"explanation_cn":"think 是不规则动词,过去式 thought。✓ Every day I thought about postcards."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l03',7,NULL,'cloze','{"stem":"第 4 空","context":"Last summer I ___1___ to Italy. A friendly waiter ___2___ me a few words of Italian. Every day I ___3___ about postcards, but I ___4___ send any.","blank_no":4,"options":["don''t","didn''t","wasn''t","weren''t"],"answer_index":1,"explanation_cn":"\"却一张也没寄\"用过去否定 didn''t + 动词原形 send。✓ but I didn''t send any."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l03',8,NULL,'choice','{"stem":"Where did the writer go last summer?","options":["Italy","Spain","Greece","France"],"answer_index":0,"explanation_cn":"听 Last summer I went to Italy,作者去的是意大利。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l03',8,NULL,'choice','{"stem":"What did the friendly waiter do?","options":["He sold postcards","He cooked dinner","He taught the writer some Italian and lent him a book","He drove the writer around"],"answer_index":2,"explanation_cn":"听 A friendly waiter taught me a few words of Italian, and then he lent me a book——服务员教了意大利语,还借了书。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l03',8,NULL,'choice','{"stem":"How many cards did the writer write?","options":["A few","Only one","Thirty-seven","None"],"answer_index":3,"explanation_cn":"作者买了 37 张卡,却 didn''t write a single card(一张也没写成),所以写成的是 None(一张也没有)。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l03',9,NULL,'choice','{"stem":"朋友问你昨晚干嘛了,你想说\"我去看了电影\"(过去时):","options":["I go to the movies.","I''m going to the movies.","I will go to the movies.","I went to the movies."],"answer_index":3,"explanation_cn":"说昨晚做过、已结束的事,用一般过去时,go→went。✓ I went to the movies. 场合:回答别人问你昨晚干了什么。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l03',9,NULL,'choice','{"stem":"你想问朋友\"你昨天去哪儿了\":","options":["Where do you go yesterday?","Where you went yesterday?","Where did you go yesterday?","Where did you went yesterday?"],"answer_index":2,"explanation_cn":"问别人昨天去了哪儿,用 Where did you go yesterday?——问过去的事,前面加 did,go 保持原形。✓ Where did you go yesterday? 场合:问对方昨天的行踪。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l03',9,NULL,'choice','{"stem":"服务员借给你一本书,你想说\"谢谢你借给我这本书\":","options":["Thank you for lending me this book.","Thank you for borrow me this book.","Thank you for borrowing me this book.","Thank you for lend me this book."],"answer_index":0,"explanation_cn":"感谢对方\"借给我\"(借出=lend),这里用动名词 lending。✓ Thank you for lending me this book. 用 borrow 就说反方向了。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l03',10,NULL,'choice','{"stem":"\"博物馆\" 对应的英文单词是:","options":["garden","theater","museum","library"],"answer_index":2,"explanation_cn":"\"博物馆\"对应 museum。✓ I visited a lot of museums."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l03',10,NULL,'choice','{"stem":"课文里 \"a single card\" 中 single 的意思是:","options":["唯一的,一张也(没写)","单身的","简单的","双人的"],"answer_index":0,"explanation_cn":"single = 唯一的、单单一个。a single card = 连一张都(没写)。✓ I didn''t write a single card."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l03',10,NULL,'choice','{"stem":"\"I ___ a book yesterday.\"(yesterday,这个动词的过去式拼写不变)","options":["reads","read","red","readed"],"answer_index":1,"explanation_cn":"read 是不规则动词,过去式拼写不变,还是 read(只是读音变了)。✓ I read a book yesterday. 别写成 readed。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l03',10,NULL,'choice','{"stem":"\"She ___ up early this morning.\"(get 的过去式)","options":["gots","geted","getted","got"],"answer_index":3,"explanation_cn":"get 是不规则动词,过去式 got。✓ She got up early. 别写成 getted。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l03',10,NULL,'choice','{"stem":"有人问 \"What happened?\",是在问:","options":["多少钱","现在几点","发生了什么事","你叫什么"],"answer_index":2,"explanation_cn":"What happened? = 发生了什么事?问出了什么状况。场合:看到异常或事故时问。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l03',10,NULL,'choice','{"stem":"\"I made a big decision.\" 意思是:","options":["我改变了主意","我下了一个重大决心","我犯了个大错","我提了个问题"],"answer_index":1,"explanation_cn":"I made a big decision = 我做了个重大决定、下了大决心。场合:郑重宣布决定。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l03',10,NULL,'choice','{"stem":"What did the writer buy on the last day?","options":["A book","A train ticket","Some food","Thirty-seven postcards"],"answer_index":3,"passage":"Postcards always spoil my vacations. Last summer I went to Italy. I visited a lot of museums and sat in public parks. The museums were free, and the weather was warm. A friendly waiter taught me a few words of Italian, and then he lent me a book. I read a few lines, but I didn''t understand a word. Every day I thought about the postcards, but I didn''t send any. My vacation passed quickly. On the last day I made a big decision. I got up early and bought thirty-seven postcards. I spent the whole day in my room, but I didn''t write a single card!","explanation_cn":"课文说 On the last day… bought thirty-seven postcards,最后一天买了 37 张明信片。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l03',10,NULL,'choice','{"stem":"Did the writer send the cards?","options":["Yes, he sent a few","Yes, he sent all of them","No, he didn''t write a single one","No, but he wrote them all"],"answer_index":2,"passage":"Postcards always spoil my vacations. Last summer I went to Italy. I visited a lot of museums and sat in public parks. The museums were free, and the weather was warm. A friendly waiter taught me a few words of Italian, and then he lent me a book. I read a few lines, but I didn''t understand a word. Every day I thought about the postcards, but I didn''t send any. My vacation passed quickly. On the last day I made a big decision. I got up early and bought thirty-seven postcards. I spent the whole day in my room, but I didn''t write a single card!","explanation_cn":"课文结尾 I didn''t write a single card——一张都没写成,更没寄出。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l03',10,NULL,'choice','{"stem":"Who lent the writer a book?","options":["A friendly waiter","A teacher","A museum guide","His friend"],"answer_index":0,"audio":"Postcards always spoil my vacations. Last summer I went to Italy. I visited a lot of museums and sat in public parks. The museums were free, and the weather was warm. A friendly waiter taught me a few words of Italian, and then he lent me a book. I read a few lines, but I didn''t understand a word. Every day I thought about the postcards, but I didn''t send any. My vacation passed quickly. On the last day I made a big decision. I got up early and bought thirty-seven postcards. I spent the whole day in my room, but I didn''t write a single card!","explanation_cn":"课文说 A friendly waiter… lent me a book,是那位友好的服务员借的书。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l03',10,NULL,'choice','{"stem":"What did the writer do on the last day?","options":["He wrote letters","He visited a museum","He left Italy","He got up early and bought postcards"],"answer_index":3,"audio":"Postcards always spoil my vacations. Last summer I went to Italy. I visited a lot of museums and sat in public parks. The museums were free, and the weather was warm. A friendly waiter taught me a few words of Italian, and then he lent me a book. I read a few lines, but I didn''t understand a word. Every day I thought about the postcards, but I didn''t send any. My vacation passed quickly. On the last day I made a big decision. I got up early and bought thirty-seven postcards. I spent the whole day in my room, but I didn''t write a single card!","explanation_cn":"课文说最后一天 I got up early and bought thirty-seven postcards。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am2_l04',2,1,4,'An exciting trip','激动人心的旅行','现在完成时(构成 have/has+过去分词 · 状语 just/already/never/ever/yet · for+时间段 · gone vs been · vs 一般过去时/现在进行时)','哥哥 Tom 移居国外(加拿大)· 来信讲这半年当工程师、游历多地、买车的新鲜经历','{"q":"Listen and answer — How long has Tom been in Canada?","options":["Six months","Three months","A year","A week"],"answer_index":0}'::jsonb,'{"title":"说\"已经做过 / 一直在\"的事(现在完成时)","intro":"本课讲怎么说\"到现在为止已经做过、或一直持续到现在\"的事。下面全用本课句子举例。","table":{"headers":["用法 / 构成","本课例子"],"rows":[["构成:have/has + 过去分词(I/you/we/they → have;he/she/it → has)","I have received a letter. / He has visited many cities."],["过去分词:规则动词=+ed(receive→received);不规则要单独记(be→been / go→gone / get→gotten / buy→bought / drive→driven)","He has already gotten a job.(get→gotten)"],["否定:have/has + not + 过去分词","He has not felt tired yet."],["疑问:Have/Has + 主语 + 过去分词?","Have you ever been to Canada?"],["have gone(去了还没回)vs have been(去过又回来了)","He has gone to Alice Springs.(还在那)/ I have been abroad.(去过)"]]},"specialRules":[{"rule":"状语 just / already / never / ever 放在 have/has 和过去分词中间;yet 放句末(多用于否定/疑问)","mark":"状语位置"},{"rule":"for + 一段时间(for six months);since + 过去时间点(since 1980)。注意:不能说 since three years,要说 since three years ago","mark":"for / since"},{"rule":"有明确的过去时间点(yesterday / last year)时,用一般过去时,不用现在完成时","mark":"vs 一般过去时"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l04',1,NULL,'My brother Tom has moved abroad.','我哥哥 Tom 搬到国外去了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l04',2,NULL,'He is now living in Canada, and he has been there for six months.','他现在住在加拿大,已经在那儿待了六个月了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l04',3,NULL,'I have just received a long letter from him.','我刚收到他一封长信。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l04',4,NULL,'Tom is an engineer, and he has already gotten a good job at a big firm.','Tom 是个工程师,他已经在一家大公司找到了一份好工作。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l04',5,NULL,'He works hard, but he has not felt tired yet.','他工作很努力,但到现在还不觉得累。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l04',6,NULL,'Since he arrived, he has traveled to a great number of different cities.','自从到那儿以后,他已经去过许多不同的城市。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l04',7,NULL,'He has recently bought a used car.','他最近买了一辆二手车。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l04',8,NULL,'Right now he has driven to a small town in the center of the country.','此刻他已经开车去了这个国家中心的一个小镇。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l04',9,NULL,'Have you ever been to Canada?','你去过加拿大吗?') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l04',10,NULL,'Tom has never lived abroad before.','Tom 以前从没在国外生活过。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l04',11,NULL,'He is finding this trip really exciting!','他觉得这趟旅行真是激动人心!') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
