INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l06',5,'am2_l06_gp1','choice','{"stem":"\"___ hour\"(hour 的 h 不发音,以元音开头)","options":["a","an","the","some"],"answer_index":1,"explanation_cn":"看发音,不看字母。hour 的 h 不发音,读起来是元音开头,所以用 an。✓ an hour / an honor。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l06',5,'am2_l06_gp1','choice','{"stem":"\"___ university\"(university 读 /juː/,辅音开头)","options":["the","some","an","a"],"answer_index":3,"explanation_cn":"university 读作 /juːnɪˈvɜːrsəti/,开头是辅音 /j/,所以用 a(不是 an)。✓ a university / a unique idea。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l06',5,'am2_l06_gp2','choice','{"stem":"\"He asked me for ___ sandwich.\"(一个,可数单数)","options":["some","a","an","the"],"answer_index":1,"explanation_cn":"sandwich 是可数名词单数,\"一个\"用 a。✓ He asked me for a sandwich."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l06',5,'am2_l06_gp2','choice','{"stem":"\"I have moved into ___ apartment.\"(apartment 元音开头)","options":["an","the","a","some"],"answer_index":0,"explanation_cn":"apartment 读音以元音开头,可数单数用 an。✓ an apartment。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l06',5,'am2_l06_gp3','choice','{"stem":"\"I gave him ___ food.\"(一些,food 不可数)","options":["an","some","a","the"],"answer_index":1,"explanation_cn":"food 是不可数名词,\"一些\"用 some(不能用 a food)。✓ I gave him some food."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l06',5,'am2_l06_gp3','choice','{"stem":"some 后面可以接:","options":["只能可数名词单数","只能形容词","只能专有名词","可数名词复数 或 不可数名词"],"answer_index":3,"explanation_cn":"some 表示\"一些/不确定数量\",后面接可数名词复数(some cookies)或不可数名词(some food);不接可数单数。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l06',5,'am2_l06_gp4','choice','{"stem":"\"He asked for a sandwich. He ate ___ sandwich.\"(再次提到同一个)","options":["an","the","some","a"],"answer_index":1,"explanation_cn":"第一次提到用 a sandwich;再次提到同一个三明治,就用 the。✓ He ate the sandwich."}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l06',5,'am2_l06_gp4','choice','{"stem":"\"A man is walking to me. ___ man is carrying a bag.\"(特指刚说的那个人)","options":["The","An","A","Some"],"answer_index":0,"explanation_cn":"第一次出现用 A man;再说到刚提过的那个人,用 The man(特指)。✓ The man is carrying a bag."}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l06',5,'am2_l06_gp5','choice','{"stem":"\"___ is good for you.\"(牛奶,泛指一类)","options":["The milks","Milk","An milk","A milk"],"answer_index":1,"explanation_cn":"泛指一类东西(牛奶),不可数名词前不加 a 也不加 the,直接说 Milk。✓ Milk is good for you."}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l06',5,'am2_l06_gp5','choice','{"stem":"泛指一类事物时,复数名词或不可数名词前:","options":["不加 the,也不加 a","一定加 a","一定加 an","一定加 the"],"answer_index":0,"explanation_cn":"泛指一整类事物时,复数名词或不可数名词前面既不加 the 也不加 a(Books are cheap. / Milk is good.)。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l06',5,'am2_l06_gp6','choice','{"stem":"\"His name is ___ Percy Buttons.\"(专有名词前)","options":["a","不填(直接 Percy Buttons)","the","an"],"answer_index":1,"explanation_cn":"人名等专有名词前不用 a 或 the,直接说名字。✓ His name is Percy Buttons."}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l06',5,'am2_l06_gp6','choice','{"stem":"选出正确的一句:","options":["I saw a Percy Buttons yesterday.","I saw the Percy Buttons yesterday.","I saw Percy Buttons yesterday.","I saw an Percy Buttons yesterday."],"answer_index":2,"explanation_cn":"人名前不加冠词,直接用名字。✓ I saw Percy Buttons yesterday.(不说 a/the Percy Buttons)"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l06',5,'am2_l06_gp7','choice','{"stem":"单数可数名词(如 computer)在句子里:","options":["可以直接单独用","前面必须加 a/an/the 等,不能光秃秃单独用","只能加 some","只能加形容词"],"answer_index":1,"explanation_cn":"单数可数名词不能单独出现,前面得有 a/an/the/my 之类。✓ I need a computer.(不能说 I need computer.)"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l06',5,'am2_l06_gp7','choice','{"stem":"\"一杯咖啡\"怎么说?","options":["a cup coffee","a coffee cup of","coffee a cup","a cup of coffee"],"answer_index":3,"explanation_cn":"coffee 论\"杯\"计量,用 a cup of coffee。✓ 语序是 a + cup + of + coffee。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l06',5,'am2_l06_gp7','choice','{"stem":"\"一块蛋糕\"(cake 不可数,论块)用:","options":["two cake","a cake","a piece of cake","an cake"],"answer_index":2,"explanation_cn":"cake 论\"块\"计量(不可数),用 a piece of cake。✓ 不能说 a cake 表示\"一块\"。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l06',5,'am2_l06_gp8','choice','{"stem":"ask sb for sth 的意思是:","options":["帮某人做事","向某人要某物","问某人是谁","替某人问问题"],"answer_index":1,"explanation_cn":"ask sb for sth = 向某人要某物。✓ He asked me for a meal.(向我讨一顿饭)"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l06',5,'am2_l06_gp8','choice','{"stem":"in return for this 的意思是:","options":["在回来的路上","为了换钱","作为对此的报答","毫无回报"],"answer_index":2,"explanation_cn":"in return for this = 作为对此的报答/回报。✓ In return for the meal, he sang a song."}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l06',5,'am2_l06_gp8','choice','{"stem":"\"He calls at every house.\" 里 call at 的意思是:","options":["给…打电话","大声喊叫","取消","拜访,光顾(某处)"],"answer_index":3,"explanation_cn":"call at + 地点 = 拜访、光顾(某处)。✓ He calls at every house once a month."}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l06',6,NULL,'choice','{"stem":"美语里\"公寓\"用:","options":["room","apartment","flat","house"],"answer_index":1,"explanation_cn":"美语里\"公寓\"用 apartment;英式用 flat。✓ I live in an apartment."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l06',6,NULL,'choice','{"stem":"美语里\"邻居\"拼作:","options":["neighbor","neighbour","nabor","neighber"],"answer_index":0,"explanation_cn":"美语\"邻居\"拼 neighbor(-or 结尾);英式 neighbour(-our 结尾)。✓ A neighbor told me about him."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l06',6,NULL,'choice','{"stem":"美语里\"曲奇饼干\"用:","options":["biscuit","cracker","cookie","bread"],"answer_index":2,"explanation_cn":"美语\"(甜)饼干\"用 cookie;英式用 biscuit。✓ He put a cookie in his pocket."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l06',6,NULL,'choice','{"stem":"in return for 的意思是:","options":["在返回时","作为报答","为了钱","免费地"],"answer_index":1,"explanation_cn":"in return for = 作为报答。✓ In return for the meal, he sang."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l06',6,NULL,'choice','{"stem":"ask sb for sth 的意思是:","options":["帮某人","替某人买","问某人是谁","向某人要某物"],"answer_index":3,"explanation_cn":"ask sb for sth = 向某人要某物。✓ He asked me for a meal."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l06',6,NULL,'choice','{"stem":"a cup of coffee 里 a cup of 表示:","options":["一滴","一箱","一杯(的量)","一壶"],"answer_index":2,"explanation_cn":"a cup of = 一杯(的量),用来计量咖啡、茶等。✓ a cup of coffee."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l06',7,NULL,'cloze','{"stem":"第 1 空","context":"I have just moved into ___1___ apartment. Yesterday ___2___ beggar knocked on my door. He asked for a sandwich, and then he ate ___3___ sandwich. I also gave him ___4___ food.","blank_no":1,"options":["an","a","the","some"],"answer_index":0,"explanation_cn":"apartment 读音元音开头,可数单数用 an。✓ an apartment."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l06',7,NULL,'cloze','{"stem":"第 2 空","context":"I have just moved into ___1___ apartment. Yesterday ___2___ beggar knocked on my door. He asked for a sandwich, and then he ate ___3___ sandwich. I also gave him ___4___ food.","blank_no":2,"options":["a","an","the","some"],"answer_index":0,"explanation_cn":"beggar 是可数单数、第一次提到,用 a。✓ a beggar knocked on my door."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l06',7,NULL,'cloze','{"stem":"第 3 空","context":"I have just moved into ___1___ apartment. Yesterday ___2___ beggar knocked on my door. He asked for a sandwich, and then he ate ___3___ sandwich. I also gave him ___4___ food.","blank_no":3,"options":["the","a","an","some"],"answer_index":0,"explanation_cn":"sandwich 前面已经提过一次,再次提到同一个用 the。✓ He ate the sandwich."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l06',7,NULL,'cloze','{"stem":"第 4 空","context":"I have just moved into ___1___ apartment. Yesterday ___2___ beggar knocked on my door. He asked for a sandwich, and then he ate ___3___ sandwich. I also gave him ___4___ food.","blank_no":4,"options":["some","a","an","the"],"answer_index":0,"explanation_cn":"food 是不可数名词,\"一些\"用 some。✓ I gave him some food."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l06',8,NULL,'choice','{"stem":"What did the beggar do in return for the food?","options":["He stood on his head and sang","He paid money","He told a long story","He washed the dishes"],"answer_index":0,"explanation_cn":"课文说 In return, the beggar stood on his head and sang a funny song,乞丐倒立唱歌作报答。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l06',8,NULL,'choice','{"stem":"What did the beggar put in his pocket?","options":["A sandwich","A cookie","A cup of coffee","A book"],"answer_index":1,"explanation_cn":"课文说 he put a cookie in his pocket,乞丐把一块饼干装进了口袋。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l06',8,NULL,'choice','{"stem":"How often does Percy Buttons call at every house?","options":["Once a year","Every day","Once a month","Once a week"],"answer_index":2,"explanation_cn":"课文说 He calls at every house once a month,他每月光顾每户一次。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l06',9,NULL,'choice','{"stem":"在咖啡店你想说\"我要一杯咖啡\":","options":["I''d like coffee of cup.","I''d like a cup of coffee.","I''d like cup of coffee.","I''d like a coffee cup."],"answer_index":1,"explanation_cn":"咖啡论杯,用 a cup of coffee。✓ I''d like a cup of coffee. 场合:在咖啡店点单。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l06',9,NULL,'choice','{"stem":"你第一次跟别人提到\"一个乞丐\",该用:","options":["the beggar","some beggar","a beggar","beggar"],"answer_index":2,"explanation_cn":"第一次跟对方提到某个人/物,用 a/an;这里 beggar 辅音开头,用 a。✓ a beggar. 场合:开始讲一件事、引出新人物。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l06',9,NULL,'choice','{"stem":"别人帮了你,你想说\"作为报答,我请你吃饭\":","options":["For return, I buy you dinner.","Return you, I buy dinner.","In return for, let me buy you dinner.","In return, let me buy you dinner."],"answer_index":3,"explanation_cn":"\"作为报答\"用 in return(后面直接接句子)。✓ In return, let me buy you dinner. 场合:别人帮了你,你想回报。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l06',10,NULL,'choice','{"stem":"beggar 的意思是:","options":["服务员","乞丐","顾客","邻居"],"answer_index":1,"explanation_cn":"beggar = 乞丐。✓ A beggar knocked on my door."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l06',10,NULL,'choice','{"stem":"\"He calls at every house.\" 里 call 的意思是:","options":["大喊","打电话","拜访,光顾","取消"],"answer_index":2,"explanation_cn":"call at + 地点 = 拜访、光顾;这里指他挨家挨户去讨饭。✓ He calls at every house."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l06',10,NULL,'choice','{"stem":"\"I saw ___ elephant.\"(elephant 元音开头)","options":["a","some","the","an"],"answer_index":3,"explanation_cn":"elephant 读音元音开头,可数单数用 an。✓ an elephant."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l06',10,NULL,'choice','{"stem":"\"___ is important for health.\"(水,泛指一类)","options":["An water","A water","Water","The waters"],"answer_index":2,"explanation_cn":"泛指一类东西(水),不可数名词前不加冠词,直接用 Water。✓ Water is important for health."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l06',10,NULL,'choice','{"stem":"\"Can I have a glass of water?\" 是在:","options":["拒绝喝水","问路","点评这杯水","要一杯水"],"answer_index":3,"explanation_cn":"Can I have a glass of water? = 我能要一杯水吗,是在要一杯水。场合:口渴时向别人要水。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l06',10,NULL,'choice','{"stem":"朋友说 \"In return, I''ll help you.\" 意思是:","options":["作为回报,我会帮你","我不会帮你","我回来再帮你","请你先帮我"],"answer_index":0,"explanation_cn":"In return, I''ll help you = 作为回报,我会帮你。场合:对方帮过你,现在他愿意回报。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l06',10,NULL,'choice','{"stem":"Why did the beggar stand on his head and sing?","options":["Because he was sick","Because he was tired","In return for the meal","To ask for money"],"answer_index":2,"passage":"I have just moved into an apartment on Oak Street. Yesterday a beggar knocked on my door. He asked me for a sandwich and a cup of coffee. In return, the beggar stood on his head and sang a funny song. I gave him some food. He ate the sandwich and drank the coffee. Then he put a cookie in his pocket and walked away. Later, a neighbor told me about him. Everybody on the street knows him — his name is Percy Buttons. He calls at every house once a month. He always asks for a meal and never takes money.","explanation_cn":"课文说乞丐 In return… stood on his head and sang,他倒立唱歌是为了报答那顿饭。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l06',10,NULL,'choice','{"stem":"Who is Percy Buttons?","options":["A singer on TV","A beggar everyone on the street knows","The writer''s old friend","The writer''s new neighbor"],"answer_index":1,"passage":"I have just moved into an apartment on Oak Street. Yesterday a beggar knocked on my door. He asked me for a sandwich and a cup of coffee. In return, the beggar stood on his head and sang a funny song. I gave him some food. He ate the sandwich and drank the coffee. Then he put a cookie in his pocket and walked away. Later, a neighbor told me about him. Everybody on the street knows him — his name is Percy Buttons. He calls at every house once a month. He always asks for a meal and never takes money.","explanation_cn":"课文说 Everybody on the street knows him. His name is Percy Buttons,他是街上人人认识的乞丐。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l06',10,NULL,'choice','{"stem":"Where has the writer just moved?","options":["Into an apartment on Oak Street","Back to his hometown","Into a hotel","To another city"],"answer_index":0,"audio":"I have just moved into an apartment on Oak Street. Yesterday a beggar knocked on my door. He asked me for a sandwich and a cup of coffee. In return, the beggar stood on his head and sang a funny song. I gave him some food. He ate the sandwich and drank the coffee. Then he put a cookie in his pocket and walked away. Later, a neighbor told me about him. Everybody on the street knows him — his name is Percy Buttons. He calls at every house once a month. He always asks for a meal and never takes money.","explanation_cn":"课文开头 I have just moved into an apartment on Oak Street,作者刚搬进 Oak 街的公寓。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l06',10,NULL,'choice','{"stem":"What did the writer give the beggar?","options":["Nothing at all","A book","Some food","Money"],"answer_index":2,"audio":"I have just moved into an apartment on Oak Street. Yesterday a beggar knocked on my door. He asked me for a sandwich and a cup of coffee. In return, the beggar stood on his head and sang a funny song. I gave him some food. He ate the sandwich and drank the coffee. Then he put a cookie in his pocket and walked away. Later, a neighbor told me about him. Everybody on the street knows him — his name is Percy Buttons. He calls at every house once a month. He always asks for a meal and never takes money.","explanation_cn":"课文说 I gave him some food,作者给了乞丐一些食物。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am2_l07',2,1,7,'Too late','为时太晚','过去进行时(was/were+V-ing · 用法过去某时正在进行 · when背景+突发一般过去 · while双进行 · vs一般过去时 · 否定/疑问)','侦探们在机场守候一批贵重钻石包裹 · 打开却发现里面全是石头和沙子','{"q":"Listen and answer — What was inside the parcel in the end?","options":["Stones and sand","Diamonds","Gold coins","Money"],"answer_index":0}'::jsonb,'{"title":"说\"过去正在做\"的事(过去进行时)","intro":"本课讲怎么说\"过去某个时刻正在进行\"的动作。全用本课句子举例。","table":{"headers":["用法 / 构成","本课例子"],"rows":[["构成:was/were + 动词-ing(I/he/she/it → was;you/we/they → were)","The detectives were waiting. / A guard was opening the parcel."],["用法:表示过去某个时刻正在进行的动作","At that moment, everyone was holding their breath."],["背景(过去进行时,历时较长)+ 突发(一般过去时,短暂),常用 when 连接","Some detectives were watching when the plane landed."],["while + 两个过去进行时,表示两件事同时进行","While one guard was keeping watch, another was opening the parcel."]]},"specialRules":[{"rule":"常用时间连词:when(当…时)/ while(在…期间,后面多接进行时)/ as(一边…一边)/ just as(正当…时)","mark":"时间连词"},{"rule":"''正在进行的背景''用过去进行时,''突然发生的一下''用一般过去时;两者常在同一句里配合","mark":"背景 vs 突发"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l07',1,NULL,'It was a cold, rainy afternoon at the airport.','那是机场一个又冷又下雨的下午。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l07',2,NULL,'The detectives were waiting near the gate all afternoon.','侦探们在登机口附近等了整整一下午。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l07',3,NULL,'They were expecting a shipment of valuable diamonds from overseas.','他们正等着一批从海外运来的贵重钻石。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l07',4,NULL,'That morning, a caller warned them that thieves were planning to steal it.','那天早上,有人打电话警告他们:小偷正打算偷走这批钻石。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l07',5,NULL,'When the plane landed, some detectives were watching the main hall.','飞机降落时,一些侦探正盯着主大厅。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l07',6,NULL,'Others were standing outside on the airfield.','另一些则站在外面的停机坪上。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l07',7,NULL,'Two workers carried the parcel into a small office.','两名工作人员把包裹搬进了一间小办公室。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l07',8,NULL,'While one guard was keeping watch at the door, another was opening the parcel.','一名警卫在门口守着,另一名则在打开那个包裹。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l07',9,NULL,'Everyone was holding their breath.','所有人都屏住了呼吸。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l07',10,NULL,'Then a detective slowly cut the precious parcel open.','接着,一名侦探慢慢把那个珍贵的包裹割开。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l07',11,NULL,'To their surprise, it was full of gray stones and sand!','令他们吃惊的是,里面装的全是灰色的石头和沙子!') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
