INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l07','keep guard / keep watch','',NULL,'/kiːp ɡɑːrd/','One guard was keeping watch at the door.','一名警卫在门口守着。','The soldiers kept guard all night.','士兵们守卫了整夜。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l07','to one''s surprise','',NULL,'/tə wʌnz sərˈpraɪz/','To their surprise, it was full of stones.','令他们吃惊的是,里面全是石头。','To my surprise, he passed the test.','令我吃惊的是,他通过了考试。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l07','be full of','',NULL,'/bi fʊl əv/','The parcel was full of stones and sand.','包裹里装满了石头和沙子。','The room was full of people.','房间里挤满了人。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l07',5,'am2_l07_gp1','choice','{"stem":"\"The detectives ___ waiting near the gate.\"(主语复数)","options":["is","were","was","are"],"answer_index":1,"explanation_cn":"过去进行时 = was/were + 动词-ing。主语 The detectives 是复数,用 were。✓ The detectives were waiting."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l07',5,'am2_l07_gp1','choice','{"stem":"\"A guard ___ opening the parcel.\"(主语单数)","options":["were","is","was","did"],"answer_index":2,"explanation_cn":"主语 A guard 是单数,用 was。✓ A guard was opening the parcel."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l07',5,'am2_l07_gp2','choice','{"stem":"\"He was ___ to the gate.\"(run 的 -ing 形式)","options":["ranning","running","runned","runing"],"answer_index":1,"explanation_cn":"run 以\"重读闭音节+单辅音\"结尾,-ing 要双写 n → running。✓ He was running to the gate."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l07',5,'am2_l07_gp2','choice','{"stem":"\"They were ___ dinner at eight.\"(have 的 -ing 形式)","options":["having","haiving","haved","haveing"],"answer_index":0,"explanation_cn":"have 以 e 结尾,变 -ing 去掉 e → having。✓ They were having dinner.（别写成 haveing）"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l07',5,'am2_l07_gp2','choice','{"stem":"\"I was ___ on the grass.\"(sit 的 -ing 形式)","options":["seating","sittting","sitting","siting"],"answer_index":2,"explanation_cn":"sit 以\"短元音+单辅音\"结尾,-ing 要双写 t → sitting。✓ I was sitting on the grass."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l07',5,'am2_l07_gp3','choice','{"stem":"\"At ten last night, I ___ a movie.\"(那个时刻正在看)","options":["watched","was watching","watch","am watching"],"answer_index":1,"explanation_cn":"\"昨晚十点那个时刻正在看\",用过去进行时 was watching。✓ At ten last night, I was watching a movie."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l07',5,'am2_l07_gp3','choice','{"stem":"过去进行时表示的是:","options":["过去某个时刻正在进行的动作","经常做的习惯","已经做完的动作","将来要做的动作"],"answer_index":0,"explanation_cn":"过去进行时表示\"过去某个时刻正在进行\"的动作,强调\"当时正在做\"。✓ Everyone was holding their breath."}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l07',5,'am2_l07_gp4','choice','{"stem":"\"The detectives were watching ___ the plane landed.\"(飞机降落这一突发动作)","options":["for","when","while","during"],"answer_index":1,"explanation_cn":"\"飞机降落\"是突然发生的一下,用 when 引出;正在进行的背景用过去进行时。✓ The detectives were watching when the plane landed."}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l07',5,'am2_l07_gp4','choice','{"stem":"\"I was having breakfast ___ the phone suddenly rang.\"","options":["when","as soon","during","while"],"answer_index":0,"explanation_cn":"\"电话突然响了\"是突发的短暂动作,用 when 连接。✓ I was having breakfast when the phone rang."}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l07',5,'am2_l07_gp5','choice','{"stem":"\"___ one guard was keeping watch, another was opening the box.\"(两件事同时进行)","options":["After","When suddenly","While","Because"],"answer_index":2,"explanation_cn":"两件事在同一段时间同时进行,用 While 连接,两个动作都用过去进行时。✓ While one guard was keeping watch, another was opening the box."}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l07',5,'am2_l07_gp5','choice','{"stem":"while 表示\"在…期间\",后面常接:","options":["祈使句","现在完成时","一般将来时","过去进行时(正在进行的动作)"],"answer_index":3,"explanation_cn":"while 意思是\"在…期间\",后面常接过去进行时,表示\"正在进行\"的动作。✓ while she was listening to the radio."}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l07',5,'am2_l07_gp6','choice','{"stem":"\"我昨晚十点正在看电视\"应说:","options":["I was watching TV at ten last night.","I watched TV at ten last night.","I have watched TV at ten last night.","I watch TV at ten last night."],"answer_index":0,"explanation_cn":"\"十点那个时刻正在看\"用过去进行时 was watching。✓ I was watching TV at ten last night."}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l07',5,'am2_l07_gp6','choice','{"stem":"was watching(过去进行时) 和 watched(一般过去时) 的区别是:","options":["was watching 表示将来","was watching 强调当时正在进行;watched 只说''做过''","was watching 强调做完了;watched 强调正在进行","两个意思完全一样"],"answer_index":1,"explanation_cn":"was watching(过去进行时)强调\"当时那一刻正在进行\";watched(一般过去时)只表示\"做过\"这件事、不强调进行。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l07',5,'am2_l07_gp7','choice','{"stem":"\"他当时没在睡觉\"的正确说法:","options":["He wasn''t slept.","He not was sleeping.","He didn''t sleeping.","He wasn''t sleeping."],"answer_index":3,"explanation_cn":"过去进行时的否定 = was/were + not + V-ing。✓ He wasn''t sleeping.（不是 didn''t sleeping,也不是 wasn''t slept）"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l07',5,'am2_l07_gp7','choice','{"stem":"\"你当时在做什么?\"的正确说法:","options":["What was you doing?","What did you doing?","What were you doing?","What you were doing?"],"answer_index":2,"explanation_cn":"过去进行时的疑问句把 was/were 提到主语前;you 用 were。✓ What were you doing?"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l07',5,'am2_l07_gp8','choice','{"stem":"keep guard / keep watch 的意思是:","options":["守卫,站岗","偷偷藏起来","放弃看守","查看时间"],"answer_index":0,"explanation_cn":"keep guard / keep watch = 守卫、站岗。✓ One guard was keeping watch at the door."}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l07',5,'am2_l07_gp8','choice','{"stem":"to their surprise 的意思是:","options":["在他们看来","为了给他们惊喜","让他们放心","令他们吃惊的是"],"answer_index":3,"explanation_cn":"to their surprise = 令他们吃惊的是。✓ To their surprise, it was full of stones."}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l07',5,'am2_l07_gp8','choice','{"stem":"be full of 的意思是:","options":["远离…","装满…,充满…","属于…","缺少…"],"answer_index":1,"explanation_cn":"be full of = 装满、充满。✓ The parcel was full of stones and sand."}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l07',6,NULL,'choice','{"stem":"美语里\"包裹\"常说:","options":["packet","parcel","package","pack"],"answer_index":2,"explanation_cn":"美语里\"包裹\"常说 package;英式用 parcel。✓ I got a package in the mail."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l07',6,NULL,'choice','{"stem":"美语里\"灰色\"拼作:","options":["gray","graye","greay","grey"],"answer_index":0,"explanation_cn":"美语\"灰色\"拼 gray;英式拼 grey。✓ gray stones."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l07',6,NULL,'choice','{"stem":"美语里\"飞机\"用:","options":["planeair","airplan","airplane","aeroplane"],"answer_index":2,"explanation_cn":"美语\"飞机\"用 airplane;英式用 aeroplane。✓ The airplane landed."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l07',6,NULL,'choice','{"stem":"keep guard 的意思是:","options":["查看时间","偷偷藏起来","放弃看守","守卫,站岗"],"answer_index":3,"explanation_cn":"keep guard = 守卫、站岗。✓ One guard was keeping watch."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l07',6,NULL,'choice','{"stem":"to their surprise 的意思是:","options":["令他们吃惊的是","使他们放心","在他们家里","为了惊喜"],"answer_index":0,"explanation_cn":"to their surprise = 令他们吃惊的是。✓ To their surprise, the parcel was full of sand."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l07',6,NULL,'choice','{"stem":"be full of 的意思是:","options":["缺少","装满,充满","来自","离开"],"answer_index":1,"explanation_cn":"be full of = 装满、充满。✓ It was full of stones."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l07',7,NULL,'cloze','{"stem":"第 1 空","context":"The detectives ___1___ waiting at the airport. When the plane ___2___, some of them ___3___ watching the main hall. While one guard ___4___ keeping watch, another opened the parcel.","blank_no":1,"options":["were","was","are","did"],"answer_index":0,"explanation_cn":"主语 The detectives 复数,过去进行时用 were + V-ing。✓ The detectives were waiting."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l07',7,NULL,'cloze','{"stem":"第 2 空","context":"The detectives ___1___ waiting at the airport. When the plane ___2___, some of them ___3___ watching the main hall. While one guard ___4___ keeping watch, another opened the parcel.","blank_no":2,"options":["landed","was landing","lands","land"],"answer_index":0,"explanation_cn":"\"飞机降落\"是突然发生的一下,用一般过去时 landed。✓ When the plane landed…"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l07',7,NULL,'cloze','{"stem":"第 3 空","context":"The detectives ___1___ waiting at the airport. When the plane ___2___, some of them ___3___ watching the main hall. While one guard ___4___ keeping watch, another opened the parcel.","blank_no":3,"options":["were","was","are","had"],"answer_index":0,"explanation_cn":"some of them 指多个侦探(复数),背景动作用过去进行时 were watching。✓ some of them were watching."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l07',7,NULL,'cloze','{"stem":"第 4 空","context":"The detectives ___1___ waiting at the airport. When the plane ___2___, some of them ___3___ watching the main hall. While one guard ___4___ keeping watch, another opened the parcel.","blank_no":4,"options":["was","were","is","did"],"answer_index":0,"explanation_cn":"one guard 单数,过去进行时用 was + V-ing。✓ While one guard was keeping watch…"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l07',8,NULL,'choice','{"stem":"Where were the detectives waiting?","options":["At home","At the train station","At the bank","At the airport"],"answer_index":3,"explanation_cn":"课文说 The detectives were waiting near the gate… at the airport,侦探们在机场等候。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l07',8,NULL,'choice','{"stem":"What were they expecting?","options":["A package of books","A shipment of valuable diamonds","A letter","A box of gold coins"],"answer_index":1,"explanation_cn":"课文说 They were expecting a shipment of valuable diamonds,他们等的是一批贵重钻石。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l07',8,NULL,'choice','{"stem":"What was inside the parcel in the end?","options":["Gold coins","Diamonds","Stones and sand","Money"],"answer_index":2,"explanation_cn":"课文结尾 it was full of gray stones and sand,包裹里其实全是石头和沙子。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l07',9,NULL,'choice','{"stem":"别人问你昨晚八点在干嘛,你想说\"我当时在做作业\":","options":["I am doing my homework.","I did my homework.","I was doing my homework.","I do my homework."],"answer_index":2,"explanation_cn":"说\"昨晚某个时刻正在做的事\",用过去进行时 was doing。✓ I was doing my homework. 场合:别人问你昨晚那会儿在忙什么。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l07',9,NULL,'choice','{"stem":"你想说\"我洗澡的时候电话响了\":","options":["The phone rings while I take a shower.","The phone rang while I was taking a shower.","The phone rang while I take a shower.","The phone was ringing while I took a shower."],"answer_index":1,"explanation_cn":"\"洗澡\"是当时正在进行的背景(过去进行时),\"电话响了\"是突发的一下(一般过去时)。✓ The phone rang while I was taking a shower. 场合:解释你为什么没接电话。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l07',9,NULL,'choice','{"stem":"你想问朋友\"我打电话时你正在做什么\":","options":["What did you do when I called you?","What you were doing when I call?","What were you do when I called?","What were you doing when I called?"],"answer_index":3,"explanation_cn":"问\"我打电话那会儿你正在做什么\",用 What were you doing。✓ What were you doing when I called? 场合:好奇对方当时在忙什么。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l07',10,NULL,'choice','{"stem":"detective 的意思是:","options":["司机","小偷","警卫","侦探"],"answer_index":3,"explanation_cn":"detective = 侦探。✓ The detectives were waiting at the airport."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l07',10,NULL,'choice','{"stem":"precious 的意思是:","options":["普通的","破旧的","珍贵的","廉价的"],"answer_index":2,"explanation_cn":"precious = 珍贵的、宝贵的。✓ the precious parcel."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l07',10,NULL,'choice','{"stem":"\"The children ___ playing in the yard.\"(过去进行时,复数)","options":["did","was","are","were"],"answer_index":3,"explanation_cn":"The children 是复数,过去进行时用 were + V-ing。✓ The children were playing in the yard."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l07',10,NULL,'choice','{"stem":"\"I ___ TV when you called.\"(当时正在看)","options":["was watching","watched","am watching","watch"],"answer_index":0,"explanation_cn":"\"你打电话时我当时正在看电视\",用过去进行时 was watching。✓ I was watching TV when you called."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l07',10,NULL,'choice','{"stem":"\"I was cooking when the doorbell rang.\" 意思是:","options":["我一边做饭一边按门铃","门铃响时我正在做饭","门铃响我才开始做饭","我做完饭门铃才响"],"answer_index":1,"explanation_cn":"I was cooking when the doorbell rang = 门铃响的那会儿,我正在做饭。场合:说自己当时正忙着做饭。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l07',10,NULL,'choice','{"stem":"别人问 \"What were you doing at noon?\" 是在问:","options":["你中午几点吃饭","中午你做完了什么","中午那会儿你正在做什么","中午你打算做什么"],"answer_index":2,"explanation_cn":"What were you doing at noon? = 中午那个时候你正在做什么。场合:问对方中午那会儿的活动。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l07',10,NULL,'choice','{"stem":"Why were the detectives at the airport?","options":["They were meeting a friend","They were catching a plane","They were on vacation","They were guarding a parcel of diamonds"],"answer_index":3,"passage":"It was a cold, rainy afternoon at the airport. The detectives were waiting near the gate all afternoon. They were expecting a shipment of valuable diamonds from overseas. That morning, a caller warned them that thieves were planning to steal it. When the plane landed, some detectives were watching the main hall. Others were standing outside on the airfield. Two workers carried the parcel into a small office. While one guard was keeping watch at the door, another was opening the parcel. Everyone was holding their breath. Then a detective slowly cut the precious parcel open. To their surprise, it was full of gray stones and sand!","explanation_cn":"课文说侦探们在守候一批贵重钻石包裹,是在看守钻石。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l07',10,NULL,'choice','{"stem":"What was the parcel really full of?","options":["Old letters","Gray stones and sand","Diamonds","Gold coins"],"answer_index":1,"passage":"It was a cold, rainy afternoon at the airport. The detectives were waiting near the gate all afternoon. They were expecting a shipment of valuable diamonds from overseas. That morning, a caller warned them that thieves were planning to steal it. When the plane landed, some detectives were watching the main hall. Others were standing outside on the airfield. Two workers carried the parcel into a small office. While one guard was keeping watch at the door, another was opening the parcel. Everyone was holding their breath. Then a detective slowly cut the precious parcel open. To their surprise, it was full of gray stones and sand!","explanation_cn":"课文结尾 it was full of gray stones and sand,包裹里其实是灰石头和沙子。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l07',10,NULL,'choice','{"stem":"What were two workers doing when the plane stopped?","options":["Flying the plane","Selling diamonds","Guarding the gate","Carrying the parcel to an office"],"answer_index":3,"audio":"It was a cold, rainy afternoon at the airport. The detectives were waiting near the gate all afternoon. They were expecting a shipment of valuable diamonds from overseas. That morning, a caller warned them that thieves were planning to steal it. When the plane landed, some detectives were watching the main hall. Others were standing outside on the airfield. Two workers carried the parcel into a small office. While one guard was keeping watch at the door, another was opening the parcel. Everyone was holding their breath. Then a detective slowly cut the precious parcel open. To their surprise, it was full of gray stones and sand!","explanation_cn":"课文说 Two workers carried the parcel into a small office,飞机停下时两名工人正把包裹搬进办公室。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l07',10,NULL,'choice','{"stem":"How did the detectives feel at the end?","options":["Surprised","Bored","Happy","Sleepy"],"answer_index":0,"audio":"It was a cold, rainy afternoon at the airport. The detectives were waiting near the gate all afternoon. They were expecting a shipment of valuable diamonds from overseas. That morning, a caller warned them that thieves were planning to steal it. When the plane landed, some detectives were watching the main hall. Others were standing outside on the airfield. Two workers carried the parcel into a small office. While one guard was keeping watch at the door, another was opening the parcel. Everyone was holding their breath. Then a detective slowly cut the precious parcel open. To their surprise, it was full of gray stones and sand!","explanation_cn":"课文说 To their surprise…,发现是石头沙子,侦探们很吃惊。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am2_l08',2,1,8,'The best and the worst','最好的和最差的','比较级和最高级(规则-er/-est · 拼写去e/双写/变y · 多音节more/most · 不规则good-better-best/bad-worse-worst/many-more-most · 比较级+than · the+最高级+in · more+名词)','乔的花园全镇最美、年年获奖;比尔的更大更勤;而''我''总因最差的花园得个小奖','{"q":"Listen and answer — Whose garden is the most beautiful in town?","options":["Joe''s","Bill''s","The writer''s","Nobody''s"],"answer_index":0}'::jsonb,'{"title":"比一比:更…、最…(比较级和最高级)","intro":"本课讲怎么说''更…''(比较级)和''最…''(最高级)。全用本课句子举例。","table":{"headers":["规则 / 构成","本课例子"],"rows":[["短词:加 -er(更…)/ 加 -est(最…);去e:large→larger;双写:big→bigger;变y:pretty→prettiest","Bill''s garden is bigger than Joe''s."],["长词(两个以上音节):前面加 more(更…)/ most(最…),不加 -er/-est","Joe''s garden is more interesting. / the most beautiful garden"],["不规则(要单独记):good→better→best;bad→worse→worst;many/much→more→most","I win a prize for the worst garden."],["比较级 + than(比…);the + 最高级 + in/of(在…中最…)","Bill works harder than Joe. / the most beautiful garden in town"]]},"specialRules":[{"rule":"more 也能直接加名词,表示''更多的'':more flowers = 更多的花","mark":"more+名词"},{"rule":"副词也有比较级:works harder(干得更卖力)/ runs faster(跑得更快)","mark":"副词比较"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l08',1,NULL,'Joe Sanders has the most beautiful garden in our whole town.','乔·桑德斯拥有我们全镇最漂亮的花园。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l08',2,NULL,'Joe''s garden is my favorite of all.','乔的花园是我最喜欢的。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l08',3,NULL,'Every year, almost everyone enters for the "Nicest Garden Competition."','每年,几乎人人都报名参加"最佳花园竞赛"。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l08',4,NULL,'But Joe wins the prize every single time.','但每次都是乔获奖。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l08',5,NULL,'Bill Frith''s garden is bigger than Joe''s, and Bill works much harder.','比尔·弗里斯的花园比乔的大,比尔也干得更卖力。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l08',6,NULL,'He also grows more flowers and colorful vegetables.','他还种了更多的花和五颜六色的蔬菜。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l08',7,NULL,'But Joe''s garden is more interesting than Bill''s.','可乔的花园比比尔的更有情趣。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l08',8,NULL,'Joe has made the neatest paths and built a wooden bridge over a small pool.','乔修了最整洁的小路,还在一个小水池上架了一座木桥。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l08',9,NULL,'His garden is only ten meters wide, but it is the prettiest one around.','他的花园只有十米宽,却是周围最漂亮的一个。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l08',10,NULL,'I love gardens too, but I do not like hard work.','我也喜欢花园,但我不喜欢干重活。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l08',11,NULL,'Each year I enter for the competition as well, and I always win a little prize for the worst garden in town!','每年我也报名参赛,却总因全镇最差的花园得个小奖!') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
