INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l08',5,'am2_l08_gp1','choice','{"stem":"\"Bill''s garden is ___ than Joe''s.\"(large 的比较级)","options":["more large","larger","largest","largeer"],"answer_index":1,"explanation_cn":"large 是短词,比较级直接在词尾加 -r(已有 e)→ larger,后面接 than。✓ Bill''s garden is larger than Joe''s."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l08',5,'am2_l08_gp1','choice','{"stem":"\"She is ___ girl in the class.\"(tall 的最高级)","options":["taller","most tallest","the most tall","the tallest"],"answer_index":3,"explanation_cn":"tall 是短词,最高级加 -est,前面加 the → the tallest。✓ She is the tallest girl in the class."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l08',5,'am2_l08_gp2','choice','{"stem":"big 的比较级是:","options":["bigest","more big","bigger","biger"],"answer_index":2,"explanation_cn":"big 是\"一个元音+一个辅音\"结尾,比较级要双写 g 再加 -er → bigger。✓ 别写成 biger。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l08',5,'am2_l08_gp2','choice','{"stem":"nice 的最高级是:","options":["most nice","niceest","nicist","nicest"],"answer_index":3,"explanation_cn":"nice 以 e 结尾,最高级直接加 -st → nicest。✓ 别写成 niceest。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l08',5,'am2_l08_gp2','choice','{"stem":"happy 的比较级是:","options":["happyer","happiest","happier","more happy"],"answer_index":2,"explanation_cn":"happy 以\"辅音+y\"结尾,比较级把 y 变 i 再加 -er → happier。✓ 别写成 happyer。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l08',5,'am2_l08_gp3','choice','{"stem":"interesting 的比较级(两个以上音节的长词)是:","options":["most interesting","more interesting","interestinger","interestingest"],"answer_index":1,"explanation_cn":"interesting 有两个以上音节(长词),比较级在前面加 more → more interesting(不加 -er)。✓"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l08',5,'am2_l08_gp3','choice','{"stem":"两个以上音节的长词,比较级和最高级怎么构成?","options":["前面加 more / most(不加 -er/-est)","双写词尾再加 -er/-est","把 y 变成 i","词尾加 -er/-est"],"answer_index":0,"explanation_cn":"两个以上音节的长词(interesting / expensive / beautiful),比较级前加 more,最高级前加 most,不再加 -er/-est。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l08',5,'am2_l08_gp4','choice','{"stem":"good 的比较级和最高级是:","options":["well / bestest","more good / most good","better / best","gooder / goodest"],"answer_index":2,"explanation_cn":"good 是不规则的,比较级 better,最高级 best,要单独记(不是 gooder/goodest)。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l08',5,'am2_l08_gp4','choice','{"stem":"bad 的最高级是:","options":["most bad","worst","baddest","worse"],"answer_index":1,"explanation_cn":"bad 是不规则的,比较级 worse,最高级 worst。✓ the worst garden。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l08',5,'am2_l08_gp4','choice','{"stem":"good、bad、many 这几个词的比较级和最高级:","options":["是不规则的,要单独记","保持不变","前面加 more/most","直接加 -er/-est"],"answer_index":0,"explanation_cn":"good→better→best、bad→worse→worst、many/much→more→most 都是不规则变化,要单独记住,不能套 -er/-est 或 more/most 的规则。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l08',5,'am2_l08_gp5','choice','{"stem":"\"Bill works ___ Joe.\"(比乔更卖力)","options":["harder then","harder as","more hard than","harder than"],"answer_index":3,"explanation_cn":"hard 的比较级 harder(副词也这样比),\"比乔\"用 than。✓ Bill works harder than Joe."}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l08',5,'am2_l08_gp5','choice','{"stem":"\"我的花园比你的大\"应说:","options":["My garden is more big than yours.","My garden is bigger as yours.","My garden is bigger than yours.","My garden is biggest than yours."],"answer_index":2,"explanation_cn":"big→bigger(双写),\"比你的\"用 than。✓ My garden is bigger than yours."}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l08',5,'am2_l08_gp6','choice','{"stem":"\"Joe has the most beautiful garden ___ our town.\"(在…中最)","options":["on","for","of","in"],"answer_index":3,"explanation_cn":"\"在……(范围)中最……\"用 the + 最高级 + in。✓ the most beautiful garden in our town."}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l08',5,'am2_l08_gp6','choice','{"stem":"选出正确的最高级句子:","options":["Mary''s dress is the most expensive.","Mary''s dress is the more expensive.","Mary''s dress is most expensive.","Mary''s dress is expensivest."],"answer_index":0,"explanation_cn":"expensive 是长词,最高级 = the most expensive。✓ Mary''s dress is the most expensive."}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l08',5,'am2_l08_gp7','choice','{"stem":"\"Bill grows ___ flowers than Joe.\"(更多的花)","options":["much","most","the most","more"],"answer_index":3,"explanation_cn":"\"更多的花\"用 more + 名词(more flowers),后面接 than。✓ Bill grows more flowers than Joe."}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l08',5,'am2_l08_gp7','choice','{"stem":"\"more flowers\" 里的 more 是什么意思?","options":["更少的","更多的(修饰名词)","非常","最多的"],"answer_index":1,"explanation_cn":"more flowers 里的 more = 更多的,直接修饰名词 flowers,表示数量更多。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l08',5,'am2_l08_gp8','choice','{"stem":"enter for the competition 的意思是:","options":["观看比赛","退出比赛","报名参加比赛","赢得比赛"],"answer_index":2,"explanation_cn":"enter for the competition = 报名参加比赛。✓ Everyone enters for the competition."}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l08',5,'am2_l08_gp8','choice','{"stem":"\"I do not like hard work.\" 里 hard work 的意思是:","options":["辛苦的活儿,重活","简单的活","没有活干","有趣的活"],"answer_index":0,"explanation_cn":"hard work = 辛苦的活儿、重体力活。✓ I do not like hard work."}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l08',6,NULL,'choice','{"stem":"美语里\"最喜欢的\"拼作:","options":["favorite","favorit","favrite","favourite"],"answer_index":0,"explanation_cn":"美语\"最喜欢的\"拼 favorite(-or 结尾);英式拼 favourite。✓ my favorite garden."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l08',6,NULL,'choice','{"stem":"美语里\"颜色\"拼作:","options":["colur","collor","colour","color"],"answer_index":3,"explanation_cn":"美语\"颜色\"拼 color;英式拼 colour。✓ colorful vegetables."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l08',6,NULL,'choice','{"stem":"美语里\"米(长度单位)\"用:","options":["metre","meeter","meter","meture"],"answer_index":2,"explanation_cn":"美语\"米(长度)\"拼 meter;英式拼 metre。✓ ten meters wide."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l08',6,NULL,'choice','{"stem":"enter for 的意思是:","options":["退出","报名参加","赢得","观看"],"answer_index":1,"explanation_cn":"enter for = 报名参加。✓ enter for the competition."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l08',6,NULL,'choice','{"stem":"win a prize 的意思是:","options":["输掉比赛","交报名费","颁发奖品","赢得奖品"],"answer_index":3,"explanation_cn":"win a prize = 赢得奖品。✓ Joe wins a prize every year."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l08',6,NULL,'choice','{"stem":"hard work 的意思是:","options":["辛苦的活儿","开心的事","一点点活","简单的事"],"answer_index":0,"explanation_cn":"hard work = 辛苦的活儿、重活。✓ I do not like hard work."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l08',7,NULL,'cloze','{"stem":"第 1 空","context":"Joe has the ___1___ (beautiful) garden in town. Bill''s garden is ___2___ (big) than Joe''s, and Bill works ___3___ (hard). But I always win a prize for the ___4___ (bad) garden!","blank_no":1,"options":["most beautiful","beautifulest","more beautiful","most beautifulest"],"answer_index":0,"explanation_cn":"beautiful 是长词,最高级 = the most beautiful。✓ Joe has the most beautiful garden."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l08',7,NULL,'cloze','{"stem":"第 2 空","context":"Joe has the ___1___ (beautiful) garden in town. Bill''s garden is ___2___ (big) than Joe''s, and Bill works ___3___ (hard). But I always win a prize for the ___4___ (bad) garden!","blank_no":2,"options":["bigger","biggest","more big","biger"],"answer_index":0,"explanation_cn":"big→bigger(双写 g),后面接 than。✓ Bill''s garden is bigger than Joe''s."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l08',7,NULL,'cloze','{"stem":"第 3 空","context":"Joe has the ___1___ (beautiful) garden in town. Bill''s garden is ___2___ (big) than Joe''s, and Bill works ___3___ (hard). But I always win a prize for the ___4___ (bad) garden!","blank_no":3,"options":["harder","hardest","more hard","harderer"],"answer_index":0,"explanation_cn":"hard 的比较级 harder。✓ Bill works harder."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l08',7,NULL,'cloze','{"stem":"第 4 空","context":"Joe has the ___1___ (beautiful) garden in town. Bill''s garden is ___2___ (big) than Joe''s, and Bill works ___3___ (hard). But I always win a prize for the ___4___ (bad) garden!","blank_no":4,"options":["worst","baddest","most bad","worse"],"answer_index":0,"explanation_cn":"bad 不规则,最高级 worst。✓ the worst garden."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l08',8,NULL,'choice','{"stem":"Whose garden is the most beautiful in town?","options":["Bill''s","The writer''s","Nobody''s","Joe''s"],"answer_index":3,"explanation_cn":"课文说 Joe Sanders has the most beautiful garden,乔的花园全镇最美。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l08',8,NULL,'choice','{"stem":"Why does Joe win the competition every year?","options":["Because his garden is the biggest","Because he works the hardest","Because his garden is the most beautiful","Because he grows the most vegetables"],"answer_index":2,"explanation_cn":"课文说乔的花园最漂亮、最有情趣,所以年年获奖。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l08',8,NULL,'choice','{"stem":"What prize does the writer win?","options":["A prize for the worst garden","A prize for the best garden","No prize at all","A prize for the most flowers"],"answer_index":0,"explanation_cn":"课文结尾说 I always win a little prize for the worst garden,作者总因最差的花园得小奖。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l08',9,NULL,'choice','{"stem":"你想说\"这本书比那本更有趣\":","options":["This book is most interesting than that one.","This book is interestinger than that one.","This book is more interesting as that one.","This book is more interesting than that one."],"answer_index":3,"explanation_cn":"interesting 是长词,比较级 more interesting,\"比那本\"用 than。✓ This book is more interesting than that one. 场合:向别人推荐一本更好看的书。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l08',9,NULL,'choice','{"stem":"你想夸朋友\"你是我们班最高的\":","options":["You are the tallest in our class.","You are the most tall in our class.","You are the taller in our class.","You are tallest in our class."],"answer_index":0,"explanation_cn":"tall 的最高级 the tallest,\"在班里\"用 in。✓ You are the tallest in our class. 场合:夸朋友个子最高。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l08',9,NULL,'choice','{"stem":"你想说\"我这次成绩比上次好\"(用比较级):","options":["My grades are more good than last time.","My grades are better than last time.","My grades are best than last time.","My grades are gooder than last time."],"answer_index":1,"explanation_cn":"good 不规则,比较级 better,\"比上次\"用 than。✓ My grades are better than last time. 场合:告诉别人自己进步了。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l08',10,NULL,'choice','{"stem":"competition 的意思是:","options":["合作","展览","表演","比赛,竞赛"],"answer_index":3,"explanation_cn":"competition = 比赛、竞赛。✓ the Nicest Garden Competition."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l08',10,NULL,'choice','{"stem":"neat 的意思是:","options":["整洁的","肮脏的","巨大的","昂贵的"],"answer_index":0,"explanation_cn":"neat = 整齐的、整洁的。✓ neat paths."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l08',10,NULL,'choice','{"stem":"\"This tree is ___ than that one.\"(tall 的比较级)","options":["tallest","more tall","taller","taler"],"answer_index":2,"explanation_cn":"tall 的比较级 taller,后接 than。✓ This tree is taller than that one."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l08',10,NULL,'choice','{"stem":"\"This is the ___ movie I''ve ever seen.\"(good 的最高级)","options":["goodest","best","most good","better"],"answer_index":1,"explanation_cn":"good 不规则,最高级 best。✓ the best movie I''ve ever seen."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l08',10,NULL,'choice','{"stem":"\"Your garden is the best in town!\" 是在:","options":["要买这个花园","问花园在哪儿","夸这个花园全镇最好","说这个花园很差"],"answer_index":2,"explanation_cn":"Your garden is the best in town = 你的花园是全镇最好的,是在称赞。场合:参观别人家花园时夸奖。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l08',10,NULL,'choice','{"stem":"别人说 \"Mine is bigger than yours.\" 意思是:","options":["你的比他的大","他的比你的大","他的和你的一样大","他的是最大的"],"answer_index":1,"explanation_cn":"Mine is bigger than yours = 我的比你的大。场合:两个人在比谁的东西大。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l08',10,NULL,'choice','{"stem":"Whose garden is bigger, Joe''s or Bill''s?","options":["Bill''s garden is bigger","They are the same size","The writer''s is bigger","Joe''s garden is bigger"],"answer_index":0,"passage":"Joe Sanders has the most beautiful garden in our whole town. Joe''s garden is my favorite of all. Every year, almost everyone enters for the \"Nicest Garden Competition.\" But Joe wins the prize every single time. Bill Frith''s garden is bigger than Joe''s, and Bill works much harder. He also grows more flowers and colorful vegetables. But Joe''s garden is more interesting than Bill''s. Joe has made the neatest paths and built a wooden bridge over a small pool. His garden is only ten meters wide, but it is the prettiest one around. I love gardens too, but I do not like hard work. Each year I enter for the competition as well, and I always win a little prize for the worst garden in town!","explanation_cn":"课文说 Bill Frith''s garden is bigger than Joe''s,比尔的花园比乔的大。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l08',10,NULL,'choice','{"stem":"Why does the writer win a prize every year?","options":["Because he has the best garden","Because he has the worst garden","Because he works the hardest","Because he grows the most flowers"],"answer_index":1,"passage":"Joe Sanders has the most beautiful garden in our whole town. Joe''s garden is my favorite of all. Every year, almost everyone enters for the \"Nicest Garden Competition.\" But Joe wins the prize every single time. Bill Frith''s garden is bigger than Joe''s, and Bill works much harder. He also grows more flowers and colorful vegetables. But Joe''s garden is more interesting than Bill''s. Joe has made the neatest paths and built a wooden bridge over a small pool. His garden is only ten meters wide, but it is the prettiest one around. I love gardens too, but I do not like hard work. Each year I enter for the competition as well, and I always win a little prize for the worst garden in town!","explanation_cn":"课文说作者总因全镇最差的花园得个小奖。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l08',10,NULL,'choice','{"stem":"What has Joe built in his garden?","options":["A swimming pool","A tall stone wall","A big house","A wooden bridge over a pool"],"answer_index":3,"audio":"Joe Sanders has the most beautiful garden in our whole town. Joe''s garden is my favorite of all. Every year, almost everyone enters for the \"Nicest Garden Competition.\" But Joe wins the prize every single time. Bill Frith''s garden is bigger than Joe''s, and Bill works much harder. He also grows more flowers and colorful vegetables. But Joe''s garden is more interesting than Bill''s. Joe has made the neatest paths and built a wooden bridge over a small pool. His garden is only ten meters wide, but it is the prettiest one around. I love gardens too, but I do not like hard work. Each year I enter for the competition as well, and I always win a little prize for the worst garden in town!","explanation_cn":"课文说 Joe has built a wooden bridge over a small pool,乔在小水池上架了座木桥。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l08',10,NULL,'choice','{"stem":"Does the writer like hard work?","options":["Yes, a little","No, he does not like hard work","He never gardens","Yes, he loves it"],"answer_index":1,"audio":"Joe Sanders has the most beautiful garden in our whole town. Joe''s garden is my favorite of all. Every year, almost everyone enters for the \"Nicest Garden Competition.\" But Joe wins the prize every single time. Bill Frith''s garden is bigger than Joe''s, and Bill works much harder. He also grows more flowers and colorful vegetables. But Joe''s garden is more interesting than Bill''s. Joe has made the neatest paths and built a wooden bridge over a small pool. His garden is only ten meters wide, but it is the prettiest one around. I love gardens too, but I do not like hard work. Each year I enter for the competition as well, and I always win a little prize for the worst garden in town!","explanation_cn":"课文说 I do not like hard work,作者不喜欢干重活。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
